      "keystrokes": "bash -lc 'cat > /app/check_brackets.py << "PY"
import sys

def is_balanced(s: str) -> bool:
    bal = 0
    for ch in s:
        if ch == "(":
            bal += 1
        elif ch == ")":
            bal -= 1
            if bal < 0:
                return False
    return bal == 0


def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    try:
        t = int(data[0].strip())
        idx = 1
    except Exception:
        t = len(data)
        idx = 0
    out = []
    for _ in range(t):
        while idx < len(data) and data[idx].strip() == "":
            idx += 1
        s = data[idx].strip() if idx < len(data) else ""
        idx += 1
        out.append("YES" if is_balanced(s) else "NO")
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
