        if(dsu.find(u) != dsu.find(v)){
            dsu.unite(u, v);
            selected[i] = 1;
            cnt++;
        }
    }

    long long resPow = 1;
    long long base = 2;
    long long e = cnt;
    while(e > 0){ if(e & 1) resPow = (resPow * base) % MOD; base = (base * base) % MOD; e >>= 1; }

    cout << resPow << " " << cnt << "\n";
    bool first = true;
    for(int i = 1; i <= n; ++i){ if(selected[i]){ if(!first) cout << ' '; cout << i; first = false; }}
    cout << "\n";
    return 0;
}
