import sys
import math

MOD = 1000000007

# Factorization by trial division

def factorize(n):
    d = {}
    x = n
    while x % 2 == 0:
        d[2] = d.get(2, 0) + 1
        x //= 2
    f = 3
    while f * f <= x:
        while x % f == 0:
            d[f] = d.get(f, 0) + 1
            x //= f
        f += 2
    if x > 1:
        d[x] = d.get(x, 0) + 1
    return d

def egcd(a,b):
    if b == 0:
        return (1, 0, a)
    x, y, g = egcd(b, a % b)
    return (y, x - (a // b) * y, g)

def inv_mod(a, mod):
    g, x, y = egcd(a, mod)
    if g != 1:
