            else:
                constraints.append((ai_exp, ti))
                if ai_exp > lower:
                    lower = ai_exp
        if fixed is not None:
            for ai_exp, ti in constraints:
                if fixed < ai_exp:
                    print(-1); return
                if (fixed - ai_exp) % ti != 0:
