            else:
                # Generalized CRT merge
                e, M = constraints[0][0] % constraints[0][1], constraints[0][1]
                for (ri, mi) in constraints[1:]:
                    a1 = e; m1 = M
                    a2 = ri % mi; m2 = mi
                    g = math.gcd(m1, m2)
