#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n; 
    vector<long long> f;
    Fenwick(int n=0): n(n), f(n+1,0) {}
    void add(int i, long long d){
        for(; i<=n; i += i & -i) f[i] += d;
    }
    long long sum(int i) const {
        long long s = 0;
        for(; i > 0; i -= i & -i) s += f[i];
        return s;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k; long long a, b; int q;
    if(!(cin >> n >> k >> a >> b >> q)) return 0;

    vector<long long> val(n+1, 0);
    Fenwick Tb(n), Ta(n); // Tb = min(val[d], b), Ta = min(val[d], a)

    for(int qi = 0; qi < q; ++qi){
        int t; cin >> t;
        if(t == 1){
            int d; long long ai; cin >> d >> ai;
            long long old = val[d];
            val[d] += ai;
            long long oldb = min(old, b);
            long long newb = min(val[d], b);
            Tb.add(d, newb - oldb);
            long long olda = min(old, a);
            long long newa = min(val[d], a);
            Ta.add(d, newa - olda);
        } else if(t == 2){
            int p; cin >> p;
            int leftEnd = p - 1;
            long long sum1 = 0;
            if(leftEnd >= 1) sum1 = Tb.sum(leftEnd);
            int afterStart = p + k;
            long long sum3 = 0;
            if(afterStart <= n) sum3 = Ta.sum(n) - Ta.sum(afterStart - 1);
            cout << (sum1 + sum3) << "\n";
        }
    }
    return 0;
}
