    eqi = None
    for i, tk in enumerate(tokens):
        if tk == '=':
            eqi = i
            break
    if eqi is None:
        return None
    target = int(tokens[eqi+1])
    k = eqi // 2 + 1
    sign = [0]*k
    sign[0] = 1
    for i in range(1, k):
        sign[i] = 1 if tokens[2*i - 1] == '+' else -1
    arr = [0]*k
    arr[0] = 1
    for i in range(1, k):
        arr[i] = 1 if sign[i] == 1 else target
    p = sum(1 for s in sign if s == 1)
    m = k - p
    current = arr[0] + sum(sign[i]*arr[i] for i in range(1, k))
    maxTotal = p*target - m
    if current > target or target > maxTotal:
