#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long maxx, maxy, w;
    if(!(cin >> maxx >> maxy >> w)) return 0;
    long long N = max(maxx, maxy);

    // rev[i]
    vector<int> rev(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        string s = to_string(i);
        reverse(s.begin(), s.end());
        rev[i] = stoi(s);
    }

    // Map reduced fraction (p,q) to an ID
    unordered_map<long long, int> idmap; // key = (p<<32) | q
    vector<int> idA(maxx + 1), idB(maxy + 1);
    int idcnt = 0;

    auto get_id = [&](int p, int q) {
        long long key = ((long long)p << 32) | (unsigned int)q;
        auto it = idmap.find(key);
        if (it != idmap.end()) return it->second;
        int nid = idcnt++;
        idmap.emplace(key, nid);
        return nid;
    };

    // Build IDs for a
    for (int a = 1; a <= maxx; ++a) {
        int g = std::gcd(a, rev[a]);
        int p = a / g;
        int q = rev[a] / g;
        idA[a] = get_id(p, q);
    }
    // Build IDs for b
    for (int b = 1; b <= maxy; ++b) {
        int g = std::gcd(b, rev[b]);
        int p = rev[b] / g;
        int q = b / g;
        idB[b] = get_id(p, q);
    }

    int numR = idcnt;
    vector<long long> A_count(numR, 0); // counts of a in current x
    for (int a = 1; a <= maxx; ++a) A_count[idA[a]]++;
    vector<long long> B_count(numR, 0); // counts of b in current y

    long long x = maxx;
    long long L = 0; // current number of lucky pairs with current x and y
    long long bestX = -1, bestY = -1;
    long long bestArea = LLONG_MAX;

    // Sweep over y
    for (int y = 1; y <= maxy; ++y) {
        int rid = idB[y];
        B_count[rid]++;
        L += A_count[rid]; // add contributions of new column

        // shrink x as much as possible while keeping L >= w, ensuring x >= 1
        while (x > 1) {
            int axrid = idA[x];
            if (L - B_count[axrid] >= w) {
                L -= B_count[axrid];
                A_count[axrid]--;
                x--;
            } else {
                break;
            }
        }

        if (L >= w) {
            long long area = x * 1LL * y;
            if (area < bestArea) {
                bestArea = area;
                bestX = x;
                bestY = y;
            }
        }
    }

    if (bestX == -1) {
        cout << -1 << "\n";
    } else {
        cout << bestX << " " << bestY << "\n";
    }
    return 0;
}
