    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) a[i] = p[i] - i;

    int M = 2 * n - 1;            // domain size for a: [-(n-1), (n-1)]
    int minV = -(n - 1);

    Fenwick cnt1(M), sum1(M), cnt2(M), sum2(M);
    auto idxVal = [&](int x) { return x + n; }; // maps value x in [-(n-1), n-1] to [1, 2n-1]

    long long total_sum1 = 0, total_sum2 = 0;
    int total_count1 = 0, total_count2 = 0;

