    sum1.add(id0, a[1]);

    total_count2 = n - 1;
    for (int i = 2; i <= n; ++i) {
        int id = idxVal(a[i]);
        cnt2.add(id, 1);
        sum2.add(id, a[i]);
        total_sum2 += a[i];
    }

    long long bestF = LLONG_MAX;
    int best_t = 1;

    for (int t = 1; t <= n; ++t) {
        int A = n - t;            // threshold for T1
        int idxA = A + n;
        long long count_le1 = cnt1.sum(idxA);
        long long sum_le1 = sum1.sum(idxA);
        long long f1 = 1LL * A * count_le1 - sum_le1 + (total_sum1 - sum_le1) - 1LL * A * (total_count1 - count_le1);

        int B = -t;                   // threshold for T2
        long long count_le2 = 0, sum_le2 = 0;
        if (B < minV) {
            count_le2 = 0; sum_le2 = 0;
        } else if (B >= (n - 1)) {
            count_le2 = total_count2; sum_le2 = total_sum2;
        } else {
            int idxB = B + n;
            count_le2 = cnt2.sum(idxB);
            sum_le2 = sum2.sum(idxB);
        }
        long long f2 = 1LL * B * count_le2 - sum_le2 + (total_sum2 - sum_le2) - 1LL * B * (total_count2 - count_le2);

        long long F = f1 + f2;
        if (F < bestF) {
            bestF = F;
            best_t = t;
        }

        if (t < n) {
            int toMove = a[t + 1];
            int idMove = idxVal(toMove);
            cnt1.add(idMove, 1);
