            total_count1 += 1;
            total_sum1 += toMove;

            cnt2.add(idMove, -1);
            sum2.add(idMove, -toMove);
            total_count2 -= 1;
            total_sum2 -= toMove;
        }
    }

    int best_k = n - best_t;
    cout << bestF << " " << best_k << "\n";
    return 0;
}
