    if (blocked[0]) {
        cout << -1 << "\n";
        return 0;
    }

    // Build free positions F (sorted)
    vector<int> F;
    F.reserve(n - m);
    for(int i = 0; i < n; ++i) if(!blocked[i]) F.push_back(i);
    int t = (int)F.size();

    // If no free positions (shouldn't happen since 0 is free), handle
    if (t == 0) {
        cout << -1 << "\n";
        return 0;
    }

    // Build NB: for cur in [0, n-1], NB[cur] = index in F of largest F[idx] <= cur, or -1
    vector<int> NB(n, -1);
    int idx = 0;
    for(int cur = 0; cur < n; ++cur){
        while (idx < t && F[idx] <= cur) idx++;
        NB[cur] = idx - 1; // could be -1 if none <= cur
