        vector<double> b(N);
        for (int i = 0; i < N; ++i){
            for (int j = 0; j < N; ++j){ int v; cin >> v; A[i][j] = (double)v; }
            double ci; cin >> ci; b[i] = ci;
        }
        vector<double> temps = solveLinear(A, b);
        MCMF mcmf(N);
        for (int i = 0; i < N; ++i){
            int Mi; cin >> Mi;
            vector<int> d(Mi);
            for (int j = 0; j < Mi; ++j) cin >> d[j];
            vector<int> f(Mi);
            for (int j = 0; j < Mi; ++j) cin >> f[j];
            for (int j = 0; j < Mi; ++j){
                int to = d[j]; int cap = f[j];
                double cost = fabs(temps[i] - temps[to]);
                mcmf.addEdge(i, to, cap, cost);
            }
        }
        auto res = mcmf.minCostMaxFlow(s, t, F);
        if (res.first < F) {
            cout << "impossible\n";
        } else {
            cout << res.second << "\n";
        }
    }
    return 0;
}
