#!/usr/bin/env python3
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    adj = [[False]*n for _ in range(n)]
    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u][v] = True
        adj[v][u] = True

    FULL = (1<<16) - 1
    # For each label s, compute which labels t are at Hamming distance 1 from s
    mask_edge = [0]*16
    for s in range(16):
        msk = 0
        for t in range(16):
            if (s ^ t) in (1,2,4,8):
                msk |= 1<<t
        mask_edge[s] = msk

    def single_value(mask):
        # Return the sole value if mask has exactly one bit set, else None
        if mask and (mask & (mask - 1)) == 0:
            return mask.bit_length() - 1
        return None

    # Domains: for each vertex, a 16-bit mask of possible labels
    domains = [FULL for _ in range(n)]
    if n > 0:
        domains[0] = 1<<0  # symmetry breaking: a_1 = 0

    # Propagation: if a vertex u has a singleton domain (label sv), propagate constraints to others
    def propagate_all(domains, start, val):
        stack = [start]
        while stack:
            u = stack.pop()
            mu = domains[u]
            sv = single_value(mu)
            if sv is None:
                continue
            for w in range(n):
                if w == u:
                    continue
                if adj[u][w]:
                    new = domains[w] & mask_edge[sv]
                else:
                    new = domains[w] & (FULL ^ mask_edge[sv])
                if new != domains[w]:
                    domains[w] = new
                    if new == 0:
                        return False
                    if (new & (new - 1)) == 0:
                        stack.append(w)
        return True

    if not propagate_all(domains, 0, 0):
        pass  # guaranteed solvable by problem statement

    sys.setrecursionlimit(10000)

    def dfs(domains):
        # Check if all assigned
        all_assigned = True
        for d in domains:
            if d == 0:
                return None
            if (d & (d - 1)) != 0:
                all_assigned = False
        if all_assigned:
            res = []
            for d in domains:
                res.append(str(d.bit_length() - 1))
            return " ".join(res)

        # MRV: pick vertex with smallest domain size > 1
        best = -1
        best_size = 17
        for i in range(n):
            d = domains[i]
            if d == 0:
                return None
            sz = d.bit_count()
            if 1 < sz < best_size:
                best = i
                best_size = sz
                if sz == 2:
                    break
        if best == -1:
            # All assigned (should be handled earlier) but keep safe
            res = [str(d.bit_length()-1) for d in domains]
            return " ".join(res)

        cur_mask = domains[best]
        for s in range(16):
            if cur_mask & (1<<s):
                new_domains = domains[:]
                new_domains[best] = 1<<s
                if not propagate_all(new_domains, best, s):
                    continue
                ans = dfs(new_domains)
                if ans is not None:
                    return ans
        return None

    ans = dfs(domains)
    if ans is None:
        ans = " ".join(["0"]*n)
    print(ans)

if __name__ == "__main__":
    solve()
