        if(!allReachable){ cout << -1 << "\n"; continue; }
        bool treeProp = true; for(int c=0;c<C;c++) if(c!=root && indegDag[c] != 1){ treeProp = false; break; }
        if(!treeProp){ cout << -1 << "\n"; continue; }
