import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    A = [int(next(it)) for _ in range(n)]
    amin = min(A)
    amax = max(A)

    def F(x: float) -> float:
        itA = iter(A)
        try:
            first = next(itA)
        except StopIteration:
            return 0.0
        b = first - x
        max_end = min_end = max_so = min_so = b
        for a in itA:
            b = a - x
            # Kadane for max subarray sum
            if max_end + b > b:
                max_end = max_end + b
            else:
                max_end = b
            if max_end > max_so:
                max_so = max_end
            # Kadane for min subarray sum
            if min_end + b < b:
                min_end = min_end + b
            else:
                min_end = b
            if min_end < min_so:
                min_so = min_end
        return max(max_so, -min_so)

    lo = amin
    hi = amax
    for _ in range(100):
        m1 = lo + (hi - lo) / 3.0
        m2 = hi - (hi - lo) / 3.0
        f1 = F(m1)
        f2 = F(m2)
        if f1 > f2:
            lo = m1
        else:
            hi = m2
    xopt = (lo + hi) / 2.0
    ans = F(xopt)
    print("{:.15f}".format(ans))

if __name__ == "__main__":
