#include <bits/stdc++.h>
using namespace std;
struct Edge{int u,v; long long w;};
const long long INF_OUT = (long long)1e18; // for output
const long long INF = (long long)4e18;     // internal large value for INF-weights

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n,m; long long L; int s,t;
    if(!(cin>>n>>m>>L>>s>>t)) return 0;
    vector<Edge> edges(m);
    vector<vector<pair<int,int>>> adj(n);
    for(int i=0;i<m;i++){
        int u,v; long long w; cin>>u>>v>>w;
        edges[i] = {u,v,w};
        adj[u].push_back({v,i});
        adj[v].push_back({u,i});
    }

    auto dijkstra = [&](int start, int mode, vector<long long>& dist, vector<int>& parN, vector<int>& parE){
        dist.assign(n, (long long)LLONG_MAX/4);
        parN.assign(n,-1);
        parE.assign(n,-1);
        using P = pair<long long,int>;
        priority_queue<P, vector<P>, greater<P>> pq;
        dist[start] = 0;
        pq.push({0,start});
        auto wof = [&](int ei)->long long{
            long long w = edges[ei].w;
            if(w == 0) return (mode==0 ? INF : 1LL);
            return w;
        };
        while(!pq.empty()){
            auto [du,u] = pq.top(); pq.pop();
            if(du != dist[u]) continue;
            for(auto [v, ei] : adj[u]){
                long long w = wof(ei);
                long long nd = du + w;
                if(nd < dist[v]){
                    dist[v] = nd;
                    parN[v] = u;
                    parE[v] = ei;
                    pq.push({nd, v});
                }
            }
        }
    };

    // Step 1: zeros as INF
    vector<long long> dist0; vector<int> pN0, pE0;
    dijkstra(s, 0, dist0, pN0, pE0);
    if(dist0[t] < L){
        cout << "NO\n";
        return 0;
    }
    if(dist0[t] == L){
        cout << "YES\n";
        for(int i=0;i<m;i++){
            long long w = edges[i].w;
            if(w == 0) w = INF_OUT;
            cout << edges[i].u << " " << edges[i].v << " " << w << "\n";
        }
        return 0;
    }

    // Step 2: zeros as 1
    vector<long long> dist1; vector<int> pN1, pE1;
    dijkstra(s, 1, dist1, pN1, pE1);
    if(dist1[t] > L){
        cout << "NO\n";
        return 0;
    }

    // dist_to_t from t with zeros as 1
    vector<long long> dist_to_t; vector<int> tmpN, tmpE;
    dijkstra(t, 1, dist_to_t, tmpN, tmpE);

    // Reconstruct path from t to s using pN1, pE1
    int cur = t;
    int chosen = -1; long long chosen_w = -1;
    int chosen_p = -1, chosen_c = -1;
    while(cur != s){
        int e = pE1[cur]; int p = pN1[cur];
        if(e == -1){ cout << "NO\n"; return 0; }
        if(edges[e].w == 0){
            long long w_needed = L - dist1[p] - dist_to_t[cur];
            if(w_needed >= 1){ chosen = e; chosen_w = w_needed; chosen_p = p; chosen_c = cur; break; }
        }
        cur = p;
    }

    if(chosen == -1){
        cout << "NO\n";
        return 0;
    }

    // Apply: set chosen edge weight to chosen_w; other zeros to 1
    for(int i=0;i<m;i++){
        if(edges[i].w == 0){
            if(i == chosen) edges[i].w = chosen_w;
            else edges[i].w = 1;
        }
    }

    // Final verification
    vector<long long> dist_final; vector<int> qN, qE;
    dijkstra(s, 1, dist_final, qN, qE);
    if(dist_final[t] != L){
        cout << "NO\n";
        return 0;
    }

    cout << "YES\n";
    for(int i=0;i<m;i++){
        cout << edges[i].u << " " << edges[i].v << " " << edges[i].w << "\n";
    }
    return 0;
}
