#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    long long s, t;
    if(!(cin >> n >> k >> s >> t)) return 0;

    vector<pair<long long,long long>> cars(n);
    long long maxV = 0;
    for(int i=0;i<n;++i){
        long long c,v; cin >> c >> v;
        cars[i] = {c, v};
        maxV = max(maxV, v);
    }

    vector<long long> g(k);
    for(int i=0;i<k;++i) cin >> g[i];
    g.push_back(0);
    g.push_back(s);
    sort(g.begin(), g.end());

    vector<long long> d;
    d.reserve(g.size()-1);
    for(size_t i=1;i<g.size();++i){
        d.push_back(g[i] - g[i-1]);
    }

    auto can = [&](long long v){
        long long sum = 0;
        for(long long dist : d){
            if(v < dist) return false; // cannot traverse this segment
            if(v >= 2*dist) sum += dist; // entire segment in accelerated mode
            else sum += (3*dist - v);   // mixed driving
            if(sum > t) return false;   // early exit if time already exceeds t
        }
        return sum <= t;
    };

    // If even the maximum tank capacity cannot suffice, no solution
    if(!can(maxV)){
        cout << -1 << "\n";
        return 0;
    }

    long long lo = 1, hi = maxV, v_min = maxV;
    while(lo <= hi){
        long long mid = lo + (hi - lo) / 2;
        if(can(mid)){
            v_min = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }

    long long best = LLONG_MAX;
    for(auto &car : cars){
        if(car.second >= v_min) best = min(best, car.first);
    }

    if(best == LLONG_MAX) cout << -1 << "\n"; else cout << best << "\n";
    return 0;
}

