MAX_VAL = 10**12

def value_of(sub: str):
    # Leading zero rule: if length > 1 and starts with '0', invalid
    if len(sub) > 1 and sub[0] == '0':
        return None
    v = int(sub)
    if v > MAX_VAL:
        return None
    return v


def best_sum_for(s: str):
    L = len(s)
    best = None
    for i in range(1, L-2):
        va = value_of(s[:i])
        if va is None:
            continue
        for j in range(i+1, L-1):
            vb = value_of(s[i:j])
            if vb is None:
                continue
            for k in range(j+1, L):
                vc = value_of(s[j:k])
                if vc is None:
                    continue
                vd = value_of(s[k:])
                if vd is None:
                    continue
                ssum = va + vb + vc + vd
                if best is None or ssum > best:
