#include <bits/stdc++.h>
using namespace std;

// Solves JOI 2017/2018 Final Problem: Commuter Pass
// Approach: Build a 3-layer graph to allow choosing a contiguous zero-cost subpath
// of any shortest S-T path. Then run Dijkstra from U in Layer0.

using ll = long long;
const ll INF = (ll)4e18;

struct Edge { int to; ll w; };

// Dijkstra on a standard graph
vector<ll> dijkstra(int n, int s, const vector<vector<pair<int,ll>>>& g) {
    vector<ll> dist(n, INF);
    dist[s] = 0;
    using P = pair<ll,int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.emplace(0, s);
    while(!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d != dist[u]) continue;
        for (auto &e : g[u]) {
            int v = e.first; ll w = e.second;
            if (dist[v] > d + w) {
                dist[v] = d + w;
                pq.emplace(dist[v], v);
            }
        }
    }
    return dist;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if(!(cin >> N >> M)) return 0;
    int S, T; cin >> S >> T; S--; T--;
    int U, V; cin >> U >> V; U--; V--;

    vector<int> A(M), B(M);
    vector<ll> C(M);
    vector<vector<pair<int,ll>>> g(N);
    for (int i = 0; i < M; ++i) {
        int a,b; ll c; cin >> a >> b >> c; --a; --b; A[i]=a; B[i]=b; C[i]=c;
        g[a].push_back({b,c});
        g[b].push_back({a,c});
    }

    // Dijkstra from S and from T on the base graph
    vector<ll> distS = dijkstra(N, S, g);
    vector<ll> distT = dijkstra(N, T, g);
    ll D = distS[T]; // shortest S->T distance

    // Build 3-layer graph: 0 = Layer0 (before zero-seg), 1 = Layer1 (inside zero-seg), 2 = Layer2 (after ending)
    int layers = 3;
    auto id = [&](int v, int layer){ return v*layers + layer; };
    int n3 = N * layers;
    vector<vector<pair<int,ll>>> G(n3);

    // 1) Base edges in Layer0 and Layer2 (normal costs) - undirected
    for (int i = 0; i < M; ++i) {
        int a = A[i], b = B[i]; ll w = C[i];
        int u0 = id(a,0), v0 = id(b,0);
        int u2 = id(a,2), v2 = id(b,2);
        // Layer0 edges
        G[u0].push_back({v0, w});
        G[v0].push_back({u0, w});
        // Layer2 edges
        G[u2].push_back({v2, w});
        G[v2].push_back({u2, w});
    }

    // 2) Termination: Layer1 -> Layer2 at same vertex (0 cost)
    for (int vtx = 0; vtx < N; ++vtx) {
        int v1 = id(vtx,1), v2 = id(vtx,2);
        G[v1].push_back({v2, 0});
    }

    // 3) SP-oriented transitions: determine which edges lie on shortest S->T paths and their orientation
    // An edge (a,b,c) lies on a shortest path with orientation a->b if distS[a] + c = distS[b] and distS[a] + c + distT[b] == D.
    // Likewise for b->a.
    for (int i = 0; i < M; ++i) {
        int a = A[i], b = B[i]; ll w = C[i];
        bool ab = false, ba = false;
        if (distS[a] + w == distS[b] && distS[a] + w + distT[b] == D) ab = true;
        if (distS[b] + w == distS[a] && distS[b] + w + distT[a] == D) ba = true;
        if (ab) {
            // Can start zero-segment by going from (a,Layer0) to (b,Layer1) with 0 cost
            int u0 = id(a,0), v1 = id(b,1);
            G[u0].push_back({v1, 0});
        }
        if (ba) {
            int u0 = id(b,0), v1 = id(a,1);
            G[u0].push_back({v1, 0});
        }
        // Note: We only add zero-start transitions for SP-oriented edges; Layer1 transitions along SP edges cost 0 will be added implicitly by when we traverse such edges in Layer1.
        // We will also allow continuing the zero-segment along SP edges by adding transitions (x,Layer1) -> (y,Layer1) with 0 cost where edge is SP-oriented x->y.
        // Implement those now:
        if (ab) {
            int x = a, y = b;
            // If we are in Layer1 at x, and there is SP-oriented x->y, move to (y,Layer1) with 0 cost
            int xL1 = id(x,1), yL1 = id(y,1);
            G[xL1].push_back({yL1, 0});
        }
