    auto id = [&](int v, int lay){ return v*L + lay; };
    int N3 = N * L;
    vector<vector<pair<int,ll>>> G(N3);

    // Determine SP edges orientation
    vector<char> ab(M, false), ba(M, false);
    for (int i = 0; i < M; ++i) {
        int a = A[i], b = B[i]; ll w = C[i];
        if (distS[a] + w == distS[b] && distS[a] + w + distT[b] == D) ab[i] = true;
        if (distS[b] + w == distS[a] && distS[b] + w + distT[a] == D) ba[i] = true;
    }

    // Layer0: SP edges forward
    for (int i = 0; i < M; ++i) {
        if (ab[i]) {
            int a = A[i], b = B[i]; ll w = C[i];
            G[id(a,0)].push_back({id(b,0), w});
        }
        if (ba[i]) {
            int a = A[i], b = B[i]; ll w = C[i];
            G[id(B[i],0)].push_back({id(A[i],0), w});
        }
    }

    // Start zero-segment transitions
    for (int i = 0; i < M; ++i) {
        if (ab[i]) {
            int a = A[i], b = B[i];
            G[id(a,0)].push_back({id(b,1), 0});
        }
        if (ba[i]) {
            int a = A[i], b = B[i];
            G[id(B[i],0)].push_back({id(A[i],1), 0});
        }
    }

    // Layer1: zero-cost continuation along SP edges
    for (int i = 0; i < M; ++i) {
        if (ab[i]) {
            int a = A[i], b = B[i];
            G[id(a,1)].push_back({id(b,1), 0});
        }
        if (ba[i]) {
            int a = A[i], b = B[i];
            G[id(B[i],1)].push_back({id(A[i],1), 0});
        }
    }

    // End zero-segment
    for (int vtx = 0; vtx < N; ++vtx) {
        G[id(vtx,1)].push_back({id(vtx,2), 0});
    }

    // Layer2: all edges with normal cost (undirected)
    for (int i = 0; i < M; ++i) {
        int a = A[i], b = B[i]; ll w = C[i];
        G[id(a,2)].push_back({id(b,2), w});
        G[id(b,2)].push_back({id(a,2), w});
    }

    // Dijkstra from start (U,0)
    int start = id(U,0);
    vector<ll> dist(N3, INF);
    dist[start] = 0;
    using P = pair<ll,int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.emplace(0, start);
    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if (d != dist[u]) continue;
        for (auto &e : G[u]){
            int v = e.first; ll w = e.second;
            if (dist[v] > d + w){ dist[v] = d + w; pq.emplace(dist[v], v);}        }
    }

    ll ans = min({ dist[id(V,0)], dist[id(V,1)], dist[id(V,2)] });
    cout << ans << "\n";

    return 0;
}
