        if (N == 0 && M == 0 && L == 0) break;
        vector<double> a(N + 1);
        for (int i = 1; i <= N; ++i) cin >> a[i];

        // Precompute cost for all intervals [l, r], length >= 2
        vector<vector<double>> cost(N + 2, vector<double>(N + 2, 0.0));
        for (int l = 1; l <= N; ++l) {
            double vmin = 1e100, vmax = -1e100;
            for (int r = l; r <= N; ++r) {
                vmin = min(vmin, a[r]);
                vmax = max(vmax, a[r]);
                int len = r - l + 1;
                if (len >= 2) {
                    int k = 2 * L; // number of quantized levels
                    double step = (vmax - vmin) / (k - 1);
                    vector<double> q(k);
                    for (int p = 0; p < k; ++p) q[p] = vmin + p * step;
                    double sum = 0.0;
                    for (int t = l; t <= r; ++t) {
                        double best = (a[t] - q[0]) * (a[t] - q[0]);
                        for (int p = 1; p < k; ++p) {
                            double dev = a[t] - q[p];
                            double val = dev * dev;
                            if (val < best) best = val;
