                        sum += best;
                    }
                    cost[l][r] = sum;
                }
            }
        }

        const double INF = 1e100;
        vector<vector<double>> dp(M + 1, vector<double>(N + 1, INF));
        dp[0][0] = 0.0;
        for (int k = 1; k <= M; ++k) {
            for (int i = 2 * k; i <= N; ++i) {
                double best = INF;
                for (int lastLen = 2; lastLen <= i - 2 * (k - 1); ++lastLen) {
                    int prev = i - lastLen;
                    if (dp[k - 1][prev] >= INF / 2) continue;
                    double cand = dp[k - 1][prev] + cost[prev + 1][i];
                    if (cand < best) best = cand;
                }
                dp[k][i] = best;
            }
        }

        double ans = dp[M][N];
        cout << ans << "\n";
    }
    return 0;
}
