// Clip polygon 'poly' by half-plane a*x + b*y + c >= 0
vector<Point> clip(const vector<Point>& poly, long double a, long double b, long double c) {
    vector<Point> out;
    if (poly.empty()) return out;
    auto f = [&](const Point& p){ return a*p.x + b*p.y + c; };
    for (size_t i = 0; i < poly.size(); ++i) {
        Point cur = poly[i];
        Point prev = poly[(i + poly.size() - 1) % poly.size()];
        long double cf = f(cur);
        long double pf = f(prev);
        bool in = (cf >= -1e-18L);
        bool pin = (pf >= -1e-18L);
        if (in) {
            if (pin) {
                out.push_back(cur);
            } else {
                long double t = pf / (pf - cf);
                Point inter{ prev.x + t*(cur.x - prev.x), prev.y + t*(cur.y - prev.y) };
                out.push_back(inter);
                out.push_back(cur);
            }
        } else {
            if (pin) {
                long double t = pf / (pf - cf);
                Point inter{ prev.x + t*(cur.x - prev.x), prev.y + t*(cur.y - prev.y) };
                out.push_back(inter);
            }
        }
    }
    return out;
}

