#include <bits/stdc++.h>
using namespace std;

struct Point { long double x, y; };

// Clip polygon 'poly' by half-plane a*x + b*y + c >= 0
vector<Point> clip(const vector<Point>& poly, long double a, long double b, long double c) {
    vector<Point> out;
    if (poly.empty()) return out;
    auto f = [&](const Point& p){ return a*p.x + b*p.y + c; };
    const long double EPS = 1e-18L;
    for (size_t i = 0; i < poly.size(); ++i) {
        Point cur = poly[i];
        Point prev = poly[(i + poly.size() - 1) % poly.size()];
        long double cf = f(cur);
        long double pf = f(prev);
        bool in = (cf >= -EPS);
        bool pin = (pf >= -EPS);
        if (in) {
            if (pin) {
                out.push_back(cur);
            } else {
                long double t = pf / (pf - cf);
                Point inter{ prev.x + t*(cur.x - prev.x), prev.y + t*(cur.y - prev.y) };
                out.push_back(inter);
                out.push_back(cur);
            }
        } else {
            if (pin) {
                long double t = pf / (pf - cf);
                Point inter{ prev.x + t*(cur.x - prev.x), prev.y + t*(cur.y - prev.y) };
                out.push_back(inter);
            }
        }
    }
    return out;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    if(!(cin >> H >> W)) return 0;
    long double mA1, mA2, mB1, mB2, mX;
    cin >> mA1 >> mA2 >> mB1 >> mB2 >> mX;
    vector<string> grid(H);
    for (int i = 0; i < H; ++i) cin >> grid[i];

    long long nA = 0, nB = 0, nX = 0;
    long double Ax = 0, Ay = 0, Bx = 0, By = 0, Xx = 0, Xy = 0; // sums of centers: x (col+0.5), y (row+0.5)

    for (int r = 0; r < H; ++r) {
        for (int c = 0; c < W; ++c) {
            char ch = grid[r][c];
            if (ch == 'A') {
                nA++;
                Ax += (c + 0.5L);
                Ay += (r + 0.5L);
            } else if (ch == 'B') {
                nB++;
                Bx += (c + 0.5L);
                By += (r + 0.5L);
            } else if (ch == 'X') {
                nX++;
                Xx += (c + 0.5L);
                Xy += (r + 0.5L);
            }
        }
    }

    // Initial domain rectangle polygon in (mA, mB) space
    vector<Point> domain;
    domain.push_back({mA1, mB1});
    domain.push_back({mA2, mB1});
    domain.push_back({mA2, mB2});
    domain.push_back({mA1, mB2});

    long double total_area = 0.0L;
    // For each tile cell with a piece, clip domain by the four inequalities
    for (int r = 0; r < H; ++r) {
        for (int c = 0; c < W; ++c) {
            char ch = grid[r][c];
            if (ch == '.') continue; // empty
            long double i = (long double)(r + 1); // 1-based row index
            long double j = (long double)(c + 1); // 1-based column index

            // Four inequalities a*mA + b*mB + c >= 0
            // 1) N1 - j*D >= 0  -> a1*mA + b1*mB + c1 >= 0
            long double a1 = Ax - j * (long double)nA;
            long double b1 = Bx - j * (long double)nB;
            long double c1 = (Xx - j * (long double)nX) * mX;

            // 2) N1 - (j+1)*D <= 0  -> ( (j+1)*nA - Ax )*mA + ( (j+1)*nB - Bx )*mB + ( (j+1)*nX - Xx )*mX >= 0
            long double a2 = (j + 1.0L) * (long double)nA - Ax;
            long double b2 = (j + 1.0L) * (long double)nB - Bx;
            long double c2 = ((j + 1.0L) * (long double)nX - Xx) * mX;

            // 3) N2 - i*D >= 0
            long double a3 = Ay - i * (long double)nA;
            long double b3 = By - i * (long double)nB;
            long double c3 = (Xy - i * (long double)nX) * mX;

            // 4) N2 - (i+1)*D <= 0
            long double a4 = (i + 1.0L) * (long double)nA - Ay;
            long double b4 = (i + 1.0L) * (long double)nB - By;
            long double c4 = ((i + 1.0L) * (long double)nX - Xy) * mX;

            vector<Point> poly = domain;
            poly = clip(poly, a1, b1, c1);
            poly = clip(poly, a2, b2, c2);
            poly = clip(poly, a3, b3, c3);
            poly = clip(poly, a4, b4, c4);

            if (poly.size() >= 3) {
                long double area = 0.0L;
                for (size_t k = 0; k < poly.size(); ++k) {
                    size_t k2 = (k + 1) % poly.size();
                    area += poly[k].x * poly[k2].y - poly[k2].x * poly[k].y;
                }
                if (area < 0) area = -area;
                total_area += area * 0.5L;
            }
        }
    }

    long double rect_area = (mA2 - mA1) * (mB2 - mB1);
    long double prob = (rect_area > 0) ? (total_area / rect_area) : 0.0L;

    cout.setf(std::ios::fixed);
    cout<<setprecision(13)<<(double)prob<<"\n";
    return 0;
}
