                    size_t k2 = (k + 1) % poly.size();
                    area += poly[k].x * poly[k2].y - poly[k2].x * poly[k].y;
                }
                if (area < 0) area = -area;
                total_area += area * 0.5L;
            }
        }
    }

    long double rect_area = (mA2 - mA1) * (mB2 - mB1);
    long double prob = (rect_area > 0) ? (total_area / rect_area) : 0.0L;

    cout.setf(std::ios::fixed);
    cout << setprecision(13) << (double)prob << "\n";
    return 0;
