#include <bits/stdc++.h>
using namespace std;
static const long long MOD = 1000000007LL;

struct Matrix {
  int n;
  vector<vector<long long>> a;
  Matrix(int n_=0, bool ident=false): n(n_), a(n_, vector<long long>(n_, 0)) {
    if (ident) for (int i = 0; i < n; ++i) a[i][i] = 1;
  }
  static Matrix identity(int n) { return Matrix(n, true); }
  Matrix operator*(const Matrix& o) const {
    Matrix r(n);
    // i-k-j loop order often good for cache
    for (int i = 0; i < n; ++i) {
      for (int k = 0; k < n; ++k) {
        long long aik = a[i][k];
        if (aik == 0) continue;
        for (int j = 0; j < n; ++j) {
          r.a[i][j] = (r.a[i][j] + aik * o.a[k][j]) % MOD;
        }
      }
    }
    return r;
  }
  vector<long long> mul_vec(const vector<long long>& v) const {
    vector<long long> res(n, 0);
    for (int i = 0; i < n; ++i) {
      long long sum = 0;
      for (int k = 0; k < n; ++k) {
        sum = (sum + a[i][k] * v[k]) % MOD;
      }
      res[i] = sum;
    }
    return res;
  }
};

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int N, K, C;
  long long T;
  if(!(cin >> N >> K >> C >> T)) return 0;

  // B_d are N x N matrices for d in [1..5]
  vector<vector<long long>> B[6];
  for (int d = 0; d <= 5; ++d) B[d].assign(N, vector<long long>(N, 0));

  for (int i = 0; i < K; ++i) {
    int a, b, t;
    cin >> a >> b >> t;
    for (int pos = 1; pos <= N; ++pos) {
      int newpos;
      if (pos >= a && pos <= a + b - 1) newpos = pos - a + 1;
      else if (pos < a) newpos = pos + b;
      else newpos = pos;
      B[t][newpos - 1][pos - 1] = (B[t][newpos - 1][pos - 1] + 1) % MOD;
    }
  }

  int dim = N * 5;
  Matrix M(dim, false);

  // Top block: DP[t+1] = sum_{d=1..5} B_d * DP[t+1-d]
  for (int d = 1; d <= 5; ++d) {
    for (int newpos = 1; newpos <= N; ++newpos) {
      for (int prevpos = 1; prevpos <= N; ++prevpos) {
        int row = newpos - 1;
        int col = (d - 1) * N + (prevpos - 1);
        long long val = B[d][newpos - 1][prevpos - 1];
        if (val) M.a[row][col] = (M.a[row][col] + val) % MOD;
      }
    }
  }

  // Shift blocks for state progression
  // DP[t] -> DP[t] in next state's second block
  for (int i = 0; i < N; ++i) M.a[N + i][ i ] = 1;
  // DP[t-1] -> DP[t-1] in next state's third block
  for (int i = 0; i < N; ++i) M.a[2 * N + i][ N + i] = 1;
  // DP[t-2] -> next's fourth block
  for (int i = 0; i < N; ++i) M.a[3 * N + i][ 2 * N + i] = 1;
  // DP[t-3] -> next's fifth block
  for (int i = 0; i < N; ++i) M.a[4 * N + i][ 3 * N + i] = 1;

  // Initial state S0: DP[0] has 1 at position C-1; others are 0. All future DP[...] are 0.
  vector<long long> S0(dim, 0);
  S0[C - 1] = 1;

  // Compute M^T
  Matrix res = Matrix::identity(dim);
  Matrix base = M;
  long long e = T;
  while (e > 0) {
    if (e & 1LL) res = res * base;
    base = base * base;
    e >>= 1LL;
  }

  vector<long long> ST = res.mul_vec(S0);
  long long ans = ST[0] % MOD; // DP[T][1]
  cout << ans << "\n";
  return 0;
}
