import sys
from functools import lru_cache

@lru_cache(None)
def sg(a, b):
    if a < b:
        a, b = b, a
    if a == b:
        return 0
    if b == 1:
        return a - 1
    if a % b == 0:
        return a // b - 1
    q = a // b
    r = a % b
    seen = set()
    for t in range(1, q):
        seen.add(sg(t * b + r, b))
    seen.add(sg(b, r))
    g = 0
    while g in seen:
        g += 1
    return g

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    t = int(next(it))
    out = []
    for _ in range(t):
        n = int(next(it))
        nim = 0
        for _ in range(n):
            a = int(next(it)); b = int(next(it))
            nim ^= sg(a, b)
        out.append('YES' if nim != 0 else 'NO')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()
