  "commands": [
    {
      "keystrokes": "cat > main.py << 'PY'
#!/usr/bin/env python3
import sys

# Check that all digits of n are within the allowed set
def digits_all_in(n, allowed):
    for ch in str(n):
        if int(ch) not in allowed:
            return False
    return True

# Count all valid solutions for given digits
def count_solutions(digs):
    allowed = set(digs)
    count = 0
    for A in digs:
        for B in digs:
            for C in digs:
                M = 100*A + 10*B + C
                for D in digs:
                    if D == 0:
                        continue
                    for E in digs:
                        P1 = M * E
                        if P1 < 100 or P1 > 999:
                            continue
                        if not digits_all_in(P1, allowed):
                            continue
                        P2 = M * D
                        if P2 < 100 or P2 > 999:
                            continue
                        if not digits_all_in(P2, allowed):
                            continue
                        P = M * (10*D + E)
                        if P < 1000 or P > 9999:
                            continue
                        if not digits_all_in(P, allowed):
                            continue
                        count += 1
    return count


def main():
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        print(0)
        return
    N = data[0]
    digs = data[1:1+N]
    print(count_solutions(digs))

if __name__ == "__main__":
    main()
PY
