#include <bits/stdc++.h>
using namespace std;

struct PairHash {
    size_t operator()(const pair<unsigned long long, unsigned long long>& p) const noexcept {
        return std::hash<unsigned long long>()((p.first << 1) ^ p.second);
    }
};

unordered_map<pair<unsigned long long, unsigned long long>, bool, PairHash> memo;

bool win(unsigned long long a, unsigned long long b) {
    if (a == 0 || b == 0) return false; // cannot move
    if (a > b) swap(a, b);
    auto key = make_pair(a, b);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    // If b is divisible by a, you can move to (a, 0) in one move via modulo
    if (b % a == 0) return memo[key] = true;
    // If a == 1, you can move to 0 in one move via modulo as well
    if (a == 1) return memo[key] = true;

    // Try all moves: b -> b - a^k for k >= 1 with a^k <= b
    __int128 p = a; // start with a^1
    while (p <= b) {
        unsigned long long sub = (unsigned long long)p;
        unsigned long long nb = b - sub;
        unsigned long long na = a, nb2 = nb;
        if (na > nb2) swap(na, nb2);
        if (!win(na, nb2)) return memo[key] = true;
        if (p > ( (__int128) b) / a) break; // next power would exceed b
        p *= a; // go to next power a^k
    }

    // Also consider the modulo move explicitly
    unsigned long long r = b % a;
    unsigned long long na2 = a, nb3 = r;
    if (na2 > nb3) swap(na2, nb3);
    if (!win(na2, nb3)) return memo[key] = true;

    memo[key] = false;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        unsigned long long a, b;
        cin >> a >> b;
        bool res = win(a, b);
        cout << (res ? "First" : "Second") << "\n";
    }
    return 0;
}
