import math
MOD = 1000000009

def C(a, k):
    if k < 0 or k > a:
        return 0
    return math.comb(a, k)

def factorial(n):
    return math.factorial(n)

def formula(n, w, b):
    Smin = max(2, n - b)
    Smax = min(w, n - 1)
    if Smin > Smax:
        return 0
    total = 0
    for s in range(Smin, Smax + 1):
        c1 = C(w - 1, s - 1)
        c2 = C(b - 1, n - s - 1)
        total += (s - 1) * c1 * c2
    return factorial(w) * factorial(b) * total

def brute(n, w, b):
    # Brute force by explicit summation over possible splits
    # x1 + y + x3 = n, x1>=1, y>=1, x3>=1
    total = 0
    for x1 in range(1, n - 1):
        for y in range(1, n - x1):
            x3 = n - x1 - y
            if x3 < 1:
                continue
            # w1 = number of white events in first stripe
            for w1 in range(x1, w - x3 + 1):
                w2 = w - w1
                if w2 < x3:
                    continue
                white1 = math.factorial(w1) * C(w1 - 1, x1 - 1)
                white2 = math.factorial(w2) * C(w2 - 1, x3 - 1)
                white_split = math.comb(w, w1)
                white_total = white_split * white1 * white2
                black_total = math.factorial(b) * C(b - 1, y - 1)
                total += white_total * black_total
    return total


def main():
    for n in range(3, 8):
        for w in range(2, 6):
            for b in range(1, 6):
                if w + b < n:
                    continue
                f = formula(n, w, b)
                br = brute(n, w, b)
                if f % MOD != br % MOD:
                    print("Mismatch for", n, w, b, f % MOD, br % MOD)
                    return
    print("All brute-force checks passed.")

if __name__ == '__main__':
    main()
