#include <bits/stdc++.h>
using namespace std;

// CF 709E - Centroids (one edge replacement allowed)
// Approach: O(n log^2 n) solution using 2D range queries via a segment tree over Euler order.

static const int MAXN = 400000 + 5;
vector<vector<int>> adj;
vector<int> parentArr, tin, tout, sz, verAtTin;
int timerDFS = 0;

// Iterative DFS to compute tin, tout, sz, parent
void iterativeDFS(int n, int root = 1) {
    parentArr.assign(n+1, 0);
    tin.assign(n+1, 0);
    tout.assign(n+1, 0);
    sz.assign(n+1, 0);
    verAtTin.assign(n+1, 0);

    // stack of (v, state) where state 0 = enter, 1 = exit
    vector<pair<int,int>> st;
    st.reserve(2*n);
    st.emplace_back(root, 0);
    parentArr[root] = 0;
    while(!st.empty()) {
        auto [v, stt] = st.back(); st.pop_back();
        if(stt == 0) {
            tin[v] = ++timerDFS;
            verAtTin[timerDFS] = v;
            st.emplace_back(v, 1);
            for(int to : adj[v]) {
                if(to == parentArr[v]) continue;
                parentArr[to] = v;
                st.emplace_back(to, 0);
            }
        } else {
            sz[v] = 1;
            for(int to : adj[v]) {
                if(to == parentArr[v]) continue;
                sz[v] += sz[to];
            }
            tout[v] = timerDFS;
        }
    }
}

// 2D range query structure: segment tree over x (tin) with sorted y = sz[x] values
vector<vector<int>> seg; // each node stores sorted vector of sz values
vector<int> arrSz; // arrSz[i] = sz[node at tin i]

void buildSeg(int node, int l, int r) {
    if(l == r) {
        seg[node] = vector<int>{ arrSz[l] };
        return;
    }
    int mid = (l + r) >> 1;
    seg[node].reserve(seg[node<<1].size() + seg[node<<1|1].size());
    buildSeg(node<<1, l, mid);
    buildSeg(node<<1|1, mid+1, r);
    // merge
    seg[node].resize(seg[node<<1].size() + seg[node<<1|1].size());
    merge(seg[node<<1].begin(), seg[node<<1].end(), seg[node<<1|1].begin(), seg[node<<1|1].end(), seg[node].begin());
}

bool querySeg(int node, int l, int r, int ql, int qr, int yl, int yr) {
    if(qr < l || r < ql) return false;
    if(ql <= l && r <= qr) {
        auto &vec = seg[node];
        auto it = lower_bound(vec.begin(), vec.end(), yl);
        if(it != vec.end() && *it <= yr) return true;
        return false;
    }
    int mid = (l + r) >> 1;
    if(querySeg(node<<1, l, mid, ql, qr, yl, yr)) return true;
    if(querySeg(node<<1|1, mid+1, r, ql, qr, yl, yr)) return true;
    return false;
}

