#include <bits/stdc++.h>
using namespace std;

static const int MAXN = 400000 + 5;
vector<vector<int>> adj;
vector<int> parentArr, tin, tout, sz, verAtTin;
int timerDFS = 0;

void iterativeDFS(int n, int root = 1) {
    parentArr.assign(n+1, 0);
    tin.assign(n+1, 0);
    tout.assign(n+1, 0);
    sz.assign(n+1, 0);
    verAtTin.assign(n+1, 0);

    vector<pair<int,int>> st;
    st.reserve(2*n);
    st.emplace_back(root, 0);
    parentArr[root] = 0;
    while(!st.empty()) {
        auto [v, stt] = st.back(); st.pop_back();
        if(stt == 0) {
            tin[v] = ++timerDFS;
            verAtTin[timerDFS] = v;
            st.emplace_back(v, 1);
            for(int to : adj[v]) {
                if(to == parentArr[v]) continue;
                parentArr[to] = v;
                st.emplace_back(to, 0);
            }
        } else {
            sz[v] = 1;
            for(int to : adj[v]) {
                if(to == parentArr[v]) continue;
                sz[v] += sz[to];
            }
            tout[v] = timerDFS;
        }
    }
}

vector<vector<int>> seg; // segment tree over x with sorted y values
vector<int> arrSz;

void buildSeg(int node, int l, int r) {
    if(l == r) {
        seg[node] = vector<int>{ arrSz[l] };
        return;
    }
    int mid = (l + r) >> 1;
    buildSeg(node<<1, l, mid);
    buildSeg(node<<1|1, mid+1, r);
    seg[node].resize(seg[node<<1].size() + seg[node<<1|1].size());
    merge(seg[node<<1].begin(), seg[node<<1].end(), seg[node<<1|1].begin(), seg[node<<1|1].end(), seg[node].begin());
}

bool querySeg(int node, int l, int r, int ql, int qr, int yl, int yr) {
    if(qr < l || r < ql) return false;
    if(ql <= l && r <= qr) {
        auto &vec = seg[node];
        auto it = lower_bound(vec.begin(), vec.end(), yl);
        if(it != vec.end() && *it <= yr) return true;
        return false;
    }
    int mid = (l + r) >> 1;
    if(querySeg(node<<1, l, mid, ql, qr, yl, yr)) return true;
    if(querySeg(node<<1|1, mid+1, r, ql, qr, yl, yr)) return true;
    return false;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if(!(cin >> n)) return 0;
    adj.assign(n+1, {});
    for(int i=0;i<n-1;i++){
        int u,v; cin>>u>>v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    iterativeDFS(n, 1);

    arrSz.assign(n+1, 0);
    for(int u=1; u<=n; ++u) arrSz[tin[u]] = sz[u];

    seg.assign(4*(n+5), {});
    buildSeg(1, 1, n);

    vector<int> ans(n+1, 0);
    struct Query { int xl, xr, yl, yr, v; };
    vector<Query> queries;
    queries.reserve(n*2);

    int half = n / 2;

    for(int v=1; v<=n; ++v){
        int parentComp = (v == 1 ? 0 : (n - sz[v]));
        int maxChild = -1, idxMaxChild = -1;
        int min1Child = INT_MAX, idxMin1Child = -1, min2Child = INT_MAX;
        int minChildAll = INT_MAX;
        int childCount = 0;
        for(int to : adj[v]){
            if(to == parentArr[v]) continue;
            ++childCount;
            int s = sz[to];
            if(s > maxChild){ maxChild = s; idxMaxChild = to; }
            if(s < min1Child){ min2Child = min1Child; min1Child = s; idxMin1Child = to; }
            else if(s < min2Child){ min2Child = s; }
            minChildAll = min(minChildAll, s);
        }
        int M = max(maxChild, parentComp);
        if(M <= half){
            ans[v] = 1;
            continue;
        }
        // child candidates
        for(int to : adj[v]){
            if(to == parentArr[v]) continue;
            if(sz[to] != M) continue;
            int otherMinChild = (to == idxMin1Child ? min2Child : min1Child);
            int s_min_from_others = min(parentComp, otherMinChild);
            int L = M - half;
            int R = half - s_min_from_others;
            int yl = max(1, L);
            int yr = R;
            if(yl <= yr){
                int xl = tin[to], xr = tout[to];
                if(xl <= xr) queries.push_back({xl,xr,yl,yr,v});
            }
        }
        // parent candidate
        if(parentComp == M && v != 1){
            int s_min_other = (childCount > 0 ? minChildAll : 0);
            int L = M - half;
            int R = half - s_min_other;
            int yl = max(1, L);
            int yr = R;
            if(yl <= yr){
                int leftL = 1, leftR = tin[v]-1;
                if(leftL <= leftR) queries.push_back({leftL,leftR,yl,yr,v});
                int rightL = tout[v]+1, rightR = n;
                if(rightL <= rightR) queries.push_back({rightL,rightR,yl,yr,v});
            }
        }
    }

    for(const auto &q : queries){
        if(ans[q.v] == 1) continue;
        if(q.xl > q.xr || q.yl > q.yr) continue;
        if(querySeg(1, 1, n, q.xl, q.xr, q.yl, q.yr)){
            ans[q.v] = 1;
        }
    }

    for(int i=1;i<=n;i++){
        cout << ans[i] << (i==n ? '\n' : ' ');
    }
    return 0;
}
