# BFS over layered graph: each layer corresponds to a capacity level.

def can(start, N, V, x):
    levels = []
    v = V
    while True:
        levels.append(v)
        if v == 0:
            break
        v //= 2
    K = len(levels)

    vis = [ [False]*N for _ in range(K) ]
    q = deque()
    vis[0][start] = True
    q.append((start, 0))
    jumped = [False]*(K-1)  # whether we have expanded jumps from layer k -> k+1
    reached = [False]*N
    reached[start] = True

    while q:
        i, k = q.popleft()
        cap = levels[k]
        # walk left
        if i > 0 and x[i] - x[i-1] <= cap and not vis[k][i-1]:
