        r, c = 0, 0
        def newline():
            nonlocal r, c
            r += 1
            c = 0
        def put_char(ch, act):
            nonlocal r, c
            if r >= h:
                return
            if c >= w:
                r += 1
                c = 0
                if r >= h:
                    return
            grid[r][c] = ch
            acts[r][c] = act
            c += 1
        def write_text(text, act, vis):
            if not vis:
                return
            for ch in text:
                put_char(ch, act)
        def extract_label(n: Node) -> str:
            out = []
            def dfs(x: Node):
                if x.name == '#text':
                    if x.text:
                        out.append(x.text)
                else:
                    for ch in x.children:
                        dfs(ch)
            dfs(n)
            return ''.join(out)
        def traverse(n: Node, vis: bool):
            nonlocal r, c
            if not vis:
                return
            if n.name == '#text':
                if n.text:
                    write_text(n.text, None, True)
                return
            if n.name == 'br':
                newline()
                return
            if n.name in ('link','button'):
                label = extract_label(n)
                if vis:
                    act = {'type': 'link' if n.name=='link' else 'button', 'target': label.strip(), 'name': label.strip()}
                    write_text(label, act, True)
                return
            new_vis = vis and n.visible
            for ch in n.children:
                traverse(ch, new_vis)
        if self.root:
            for ch in self.root.children:
                traverse(ch, True)
        lines = [''.join(grid[i]) for i in range(h)]
        return lines, acts

    def execute_subroutine(self, name: str):
        if not self.ds:
            return
        stmts = self.ds.get(name, [])
        for st in stmts:
            s = (st or '').strip()
            if not s or '=' not in s:
                continue
            parts = [p.strip() for p in s.split('=')]
            rhs = parts[-1]
            if rhs == 'true':
                val = True
            elif rhs == 'false':
                val = False
            else:
                val = get_visible_by_path(self.root, split_path(rhs))
            for i in range(len(parts)-2, -1, -1):
                lhs = parts[i]
                neg = False
                if lhs.endswith('!'):
                    neg = True
                    lhs = lhs[:-1].rstrip()
                lhs_tokens = split_path(lhs)
                if lhs_tokens and lhs_tokens[-1] == 'visible':
                    target_path = lhs_tokens[:-1]
                else:
                    target_path = lhs_tokens
                targets = resolve_path(self.root, target_path)
                assign_val = (not val) if neg else val
                for node in targets:
                    node.visible = bool(assign_val)
                if target_path:
                    val = get_visible_by_path(self.root, target_path)
                else:
                    val = True

