    data = sys.stdin.read().splitlines()
    it = iter(data)
    try:
        N = int(next(it).strip())
    except StopIteration:
        return
    files = {}
    for _ in range(N):
        fname = next(it).strip()
        fcontent = next(it)
        files[fname] = fcontent
    M = int(next(it).strip())
    outputs = []
    for _ in range(M):
