        for _ in range(s):
            x, y = map(int, next(it).split())
            coords.append((x, y))
        state = State(w, h, files)
        state.load_dml(start)
        for (x, y) in coords:
            lines, acts = state.render()
            if 0 <= y < h and 0 <= x < w:
                act = acts[y][x]
                if act:
                    if act.get('type') == 'link':
                        target = act.get('target')
                        if target:
                            state.load_dml(target + '.dml')
                    elif act.get('type') == 'button':
                        btn = act.get('name')
                        if btn:
                            state.execute_subroutine(btn)
        final_lines, _ = state.render()
        outputs.extend(final_lines)
    print('\n'.join(outputs))

if __name__ == '__main__':
    main()
