using namespace std;

struct Circle { double x,y,r; };
struct Pt { double x,y; };
static Pt S{25.0,0.0};
static Pt G{25.0,94.0};

vector<Circle> circs;
int N,D;

double distance(const Pt&a,const Pt&b){ double dx=a.x-b.x, dy=a.y-b.y; return sqrt(dx*dx+dy*dy); }

double segDistToCircle(const Pt&A, const Pt&B, const Circle& c){
  double vx=B.x-A.x, vy=B.y-A.y; double vv=vx*vx+vy*vy; 
  if(vv<=1e-18) return hypot(A.x-c.x, A.y-c.y);
  double t=((c.x-A.x)*vx+(c.y-A.y)*vy)/vv; if(t<0) t=0; else if(t>1) t=1;
  double cx=A.x+t*vx, cy=A.y+t*vy; double dx=c.x-cx, dy=c.y-cy; return sqrt(dx*dx+dy*dy);
}

int sectionsForP(const Pt&P){
  int cnt = 0;
  // SP: S -> P
  for(const auto& c: circs){ if(segDistToCircle(S,P,c) < c.r - 1e-12) cnt++; }
  // PG: P -> G
  for(const auto& c: circs){ if(segDistToCircle(P,G,c) < c.r - 1e-12) cnt++; }
  return cnt;
}

double L(const Pt&P){ return distance(S,P) + distance(P,G); }
bool inRect(const Pt&P){ return P.x>0 && P.x<50 && P.y>0 && P.y<94; }

