  const double minX=0.0, maxX=50.0, minY=0.0, maxY=94.0;
  const int GRID = 180; // grid resolution for coarse search
  for(int ix=0; ix<GRID; ++ix){
    double x = minX + (maxX-minX) * (ix + 0.5) / GRID;
    for(int iy=0; iy<GRID; ++iy){
      double y = minY + (maxY-minY) * (iy + 0.5) / GRID;
      Pt P{x,y};
      int sec = sectionsForP(P);
      if(sec <= D){ double Lp = L(P); if(Lp < best) best = Lp; }
    }
  }

