#include <bits/stdc++.h>
using namespace std;

struct FenwickULL {
    int n; vector<unsigned long long> f;
    FenwickULL(int n=0){ init(n); }
    void init(int n_){ n = n_; f.assign(n+1, 0ULL); }
    void add(int i, unsigned long long delta){ for(; i<=n; i += i & -i) f[i] += delta; }
    unsigned long long sum(int i){ unsigned long long s=0; for(; i>0; i -= i & -i) s += f[i]; return s; }
    unsigned long long rangeSum(int l, int r){ if(r<l) return 0ULL; return sum(r) - sum(l-1); }
    int kth(unsigned long long k){ // smallest idx with prefix sum >= k
        int idx = 0;
        int bitMask = 1;
        while ((bitMask << 1) <= n) bitMask <<= 1;
        for (int d = bitMask; d; d >>= 1){
            int next = idx + d;
            if (next <= n && f[next] < k){
                idx = next;
                k -= f[next];
            }
        }
        return idx + 1;
    }
};

struct Fenwick128 {
    int n; vector<__int128> f;
    Fenwick128(int n=0){ init(n); }
    void init(int n_){ n = n_; f.assign(n+1, 0); }
    void add(int i, __int128 delta){ for(; i<=n; i += i & -i) f[i] += delta; }
    __int128 sum(int i){ __int128 s=0; for(; i>0; i -= i & -i) s += f[i]; return s; }
    __int128 rangeSum(int l, int r){ if(r<l) return 0; return sum(r) - sum(l-1); }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    if(!(cin >> n >> q)) return 0;
    vector<long long> a(n+1), w(n+1), d(n+1);
    for(int i=1;i<=n;i++) cin >> a[i];
    for(int i=1;i<=n;i++){ cin >> w[i]; }
    for(int i=1;i<=n;i++) d[i] = a[i] - i;

    FenwickULL bitW(n);
    Fenwick128 bitWD(n);
    for(int i=1;i<=n;i++){
        bitW.add(i, (unsigned long long)w[i]);
        __int128 val = (__int128)w[i] * (__int128)d[i];
        bitWD.add(i, val);
    }

    const long long MOD = 1000000007LL;
    for(int qi=0; qi<q; ++qi){
        long long x, y;
        cin >> x >> y;
        if(x < 0){
            int id = (int)(-x);
            long long nw = y;
            long long delta = nw - w[id];
            w[id] = nw;
            if(delta != 0){
                bitW.add(id, (unsigned long long)delta);
                __int128 dv = (__int128)delta * (__int128)d[id];
                bitWD.add(id, dv);
            }
        } else {
            int l = (int)x;
            int r = (int)y;
            unsigned long long W_total = bitW.rangeSum(l, r);
            unsigned long long W_before = bitW.sum(l-1);
            unsigned long long target = (W_total + 1) / 2;
            unsigned long long Kth = W_before + target;
            int p = bitW.kth(Kth); // median index
            long long dp = d[p];
            unsigned long long W_left = bitW.rangeSum(l, p);
            __int128 S_left = bitWD.rangeSum(l, p);
            unsigned long long W_right = W_total - W_left;
            __int128 S_total = bitWD.rangeSum(l, r);
            __int128 S_right = S_total - S_left;
            __int128 cost = (__int128)dp * ( (__int128)W_left - (__int128)W_right ) - S_left + S_right;
            long long ans = (long long)(cost % MOD);
            if(ans < 0) ans += MOD;
            cout << ans << "\n";
        }
    }
    return 0;
}
