using namespace std;

struct FenwickULL {
    int n; vector<unsigned long long> f;
    FenwickULL(int n=0){ init(n); }
    void init(int n_){ n = n_; f.assign(n+1, 0ULL); }
    void add(int i, unsigned long long delta){ for(; i<=n; i += i & -i) f[i] += delta; }
    unsigned long long sum(int i){ unsigned long long s=0; for(; i>0; i -= i & -i) s += f[i]; return s; }
    unsigned long long rangeSum(int l, int r){ if(r<l) return 0ULL; return sum(r) - sum(l-1); }
    int kth(unsigned long long k){ // smallest idx with prefix sum >= k
        int idx = 0;
        int bitMask = 1;
        while ((bitMask << 1) <= n) bitMask <<= 1;
        for (int d = bitMask; d; d >>= 1){
            int next = idx + d;
            if (next <= n && f[next] < k){
                idx = next;
                k -= f[next];
            }
        }
        return idx + 1;
    }
};

struct Fenwick128 {
    int n; vector<__int128> f;
    Fenwick128(int n=0){ init(n); }
    void init(int n_){ n = n_; f.assign(n+1, 0); }
    void add(int i, __int128 delta){ for(; i<=n; i += i & -i) f[i] += delta; }
