    int n;
    if(!(cin >> n)) return 0;
    vector<long long> a(n);
    for(int i = 0; i < n; ++i) cin >> a[i];

    if(n <= 2){
        cout << -1 << "\n";
        return 0;
    }

    bool all_eq = true;
    for(int i = 1; i < n; ++i){
        if(a[i] != a[0]){ all_eq = false; break; }
    }
    if(all_eq){
        cout << -1 << "\n";
        return 0;
    }

    int m = n - 1; // number of adjacent pairs
    vector<char> up(m, 0), down(m, 0); // up[i]: a[i] <= a[i+1], down[i]: a[i] >= a[i+1]
    int cntUp = 0, cntDown = 0;
    for(int i = 0; i < m; ++i){
        up[i] = (a[i] <= a[i+1]);
        down[i] = (a[i] >= a[i+1]);
        cntUp += up[i];
        cntDown += down[i];
    }

    auto valueAfterSwap = [&](int idx, int i, int j)->long long{
        if(idx == i) return a[j];
        if(idx == j) return a[i];
        return a[idx];
    };

    auto is_unsorted_after_swap = [&](int i, int j)->bool{
        if(i == j) return false;
        if(a[i] == a[j]) return false;
        // swap and check using local delta on affected adjacent pairs
        swap(a[i], a[j]);
        array<int,4> tmp = {i-1, i, j-1, j};
        vector<int> P;
        for(int idx : tmp){ if(idx >= 0 && idx < m) P.push_back(idx); }
        sort(P.begin(), P.end());
        P.erase(unique(P.begin(), P.end()), P.end());

        int diffUp = 0, diffDown = 0;
        auto val = [&](int idx)->long long{ return valueAfterSwap(idx, i, j); };
        for(int p : P){
            long long L = val(p);
            long long R = val(p+1);
            bool oldUp = up[p];
            bool oldDown = down[p];
            bool newUp = (L <= R);
            bool newDown = (L >= R);
            diffUp   += (int)newUp - (int)oldUp;
            diffDown += (int)newDown - (int)oldDown;
        }
        int newCntUp = cntUp + diffUp;
        int newCntDown = cntDown + diffDown;
        bool sortedAfter = (newCntUp == m) || (newCntDown == m);
        swap(a[i], a[j]); // revert
        return !sortedAfter; // true if the array is unsorted after swap
    };

    auto test = [&](int i, int j)->bool{
        if(i < 0 || j < 0 || i >= n || j >= n || i == j) return false;
        if(a[i] == a[j]) return false;
        if(is_unsorted_after_swap(i, j)){
            cout << i + 1 << " " << j + 1 << "\n";
            return true;
        }
        return false;
    };

    // Build candidate swaps
    vector<pair<int,int>> cand;
    // all adjacent unequal pairs
    for(int i = 0; i + 1 < n; ++i){
        if(a[i] != a[i+1]) cand.emplace_back(i, i+1);
    }
    // cross-end and near-end candidates
    int l = -1; for(int i = 1; i < n; ++i) if(a[i] != a[0]){ l = i; break; }
    int r = -1; for(int i = n - 2; i >= 0; --i) if(a[i] != a[n-1]){ r = i; break; }
    if(l != -1) cand.emplace_back(0, l);
    if(r != -1) cand.emplace_back(r, n-1);
    if(l != -1 && r != -1) cand.emplace_back(l, r);
    if(l != -1) cand.emplace_back(l, n-1);
    if(r != -1) cand.emplace_back(0, r);
    if(a[0] != a[n-1]) cand.emplace_back(0, n-1);

    sort(cand.begin(), cand.end());
    cand.erase(unique(cand.begin(), cand.end()), cand.end());

    for(auto &p : cand){
        if(test(p.first, p.second)) return 0;
    }

    cout << -1 << "\n";
    return 0;
