int update(int prev, int l, int r, int pos){
    int cur = (int)seg.size();
    seg.push_back(seg[prev]);
    if(l==r){
        seg[cur].sum = seg[prev].sum + 1;
        seg[cur].left = 0;
        seg[cur].right = 0;
        return cur;
    }
    int mid = (l+r)>>1;
    if(pos <= mid){
        int nl = update(seg[prev].left, l, mid, pos);
        seg[cur].left = nl;
    } else {
        int nr = update(seg[prev].right, mid+1, r, pos);
        seg[cur].right = nr;
    }
    seg[cur].sum = seg[seg[cur].left].sum + seg[seg[cur].right].sum;
    return cur;
