#include <bits/stdc++.h>
using namespace std;
int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n, w; long long k;
  if(!(cin>>n>>w>>k)) return 0;
  vector<long long> a(n), t(n);
  for(int i=0;i<n;++i) cin>>a[i];
  for(int i=0;i<n;++i) cin>>t[i];
  long long best = 0;
  int r = -1;
  long long sumT = 0, sumA = 0;
  multiset<long long> L, R; // L stores top-w largest floor halves, R stores the rest
  long long sumhalf = 0; // sum of elements in L

  auto addVal = [&](long long x){
    R.insert(x);
    if ((int)L.size() < w) {
      auto it = prev(R.end()); long long v = *it; R.erase(it); L.insert(v); sumhalf += v;
    }
    while(!R.empty() && !L.empty()){
      long long minL = *L.begin(); long long maxR = *prev(R.end());
      if (maxR > minL) {
        auto itLmin = L.begin(); long long vLmin = *itLmin; L.erase(itLmin); sumhalf -= vLmin; R.insert(vLmin);
        auto itRmax = R.find(maxR); if(itRmax!=R.end()) R.erase(itRmax);
        L.insert(maxR); sumhalf += maxR;
      } else break;
    }
  };

  auto removeVal = [&](long long x){
    auto itL = L.find(x); if (itL != L.end()) { L.erase(itL); sumhalf -= x; }
    else { auto itR = R.find(x); if (itR != R.end()) R.erase(itR); }
    if ((int)L.size() < w && !R.empty()) { auto it = prev(R.end()); long long v = *it; R.erase(it); L.insert(v); sumhalf += v; }
    while(!R.empty() && !L.empty()){
      long long minL = *L.begin(); long long maxR = *prev(R.end());
      if (maxR > minL) {
        auto itLmin = L.begin(); long long vLmin = *itLmin; L.erase(itLmin); sumhalf -= vLmin; R.insert(vLmin);
        auto itRmax = R.find(maxR); if (itRmax != R.end()) R.erase(itRmax);
        L.insert(maxR); sumhalf += maxR;
      } else break;
    }
  };

  long long totalBest = 0; // best pleasure
  for(int l=0; l<n; ++l){
    while (r+1 < n){ int idx = r+1; long long x = t[idx]/2; addVal(x); sumT += t[idx]; sumA += a[idx]; if (sumT - sumhalf <= k) { r++; } else { sumT -= t[idx]; sumA -= a[idx]; removeVal(x); break; } }
    if (sumA > totalBest) totalBest = sumA;
    if (r >= l){ long long x = t[l]/2; sumT -= t[l]; sumA -= a[l]; removeVal(x); } else { r = l; }
  }
  cout << totalBest << '\n';
  return 0;
}
