#include <bits/stdc++.h>
using namespace std;

// Fenwick (Binary Indexed Tree) for 0..N-1 domain
struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n_ = 0) { init(n_); }
    void init(int n_) { n = n_; bit.assign(n + 1, 0); }
    // add delta at index idx (0-based)
    void add(int idx, long long delta) {
        for (int i = idx + 1; i <= n; i += i & -i) bit[i] += delta;
    }
    // sum of [0..idx], idx can be -1 for empty range
    long long sumPrefix(int idx) const {
        if (idx < 0) return 0;
        long long res = 0;
        for (int i = idx + 1; i > 0; i -= i & -i) res += bit[i];
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, w; long long k;
    if(!(cin >> n >> w >> k)) return 0;
    vector<long long> a(n), t(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> t[i];

    // Savings s_i = floor(t[i] / 2), domain 0..5000 (since t[i] <= 1e4)
    const int MAXS = 5000;
    Fenwick cnt(MAXS + 1), sumv(MAXS + 1);
    long long totalCount = 0; // number of songs in window
    long long totalSum = 0;   // sum of savings in window

    long long sumT = 0; // sum of t in window
    long long sumA = 0; // sum of a in window
    long long best = 0;

    auto addValue = [&](int s){
        cnt.add(s, 1);
        sumv.add(s, s);
        totalCount += 1;
        totalSum += s;
    };

    auto removeValue = [&](int s){
        cnt.add(s, -1);
        sumv.add(s, -s);
        totalCount -= 1;
        totalSum -= s;
    };

    auto topKSum = [&](long long kTop) -> long long {
        if (kTop <= 0) return 0LL;
        if (totalCount <= kTop) {
            return totalSum;
        }
        // countGE(val) = number of elements with value >= val
        auto countGE = [&](int val)->long long {
            if (val > MAXS) return 0LL;
            long long le = (val - 1 >= 0 ? cnt.sumPrefix(val - 1) : 0LL);
            return totalCount - le;
        };
        int low = 0, high = MAXS;
        while (low < high) {
            int mid = (low + high + 1) / 2;
            if (countGE(mid) >= kTop) low = mid; else high = mid - 1;
        }
        int thr = low; // k-th largest value
        long long countGreater = countGE(thr + 1);
        long long sumGreater = totalSum - sumv.sumPrefix(thr);
        long long need = kTop - countGreater;
        long long res = sumGreater + 1LL * thr * need;
        return res;
    };

    int l = 0, r = -1; // window [l..r]
    while (l < n) {
        // extend r as far as possible
        while (r + 1 < n) {
            int newS = (int)(t[r + 1] / 2);
            sumT += t[r + 1];
            sumA += a[r + 1];
            addValue(newS);
            long long topSum = topKSum(min<long long>(w, totalCount));
            if (sumT - topSum <= k) {
                r++;
            } else {
                // revert addition
                sumT -= t[r + 1];
                sumA -= a[r + 1];
                removeValue(newS);
                break;
            }
        }
        // update best for current valid window
        if (sumA > best) best = sumA;
        // move left boundary
        if (l <= r) {
            int leftS = (int)(t[l] / 2);
            sumT -= t[l];
            sumA -= a[l];
            removeValue(leftS);
            l++;
        } else {
            // window empty, advance both pointers
            l++;
            r = -1;
        }
    }

    cout << best << '\n';
    return 0;
}
