import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 2)
    def update(self, i, val):
        n = self.n
        while i <= n:
            if val > self.bit[i]:
                self.bit[i] = val
            i += i & -i
    def query(self, i):
        res = 0
        while i > 0:
            if self.bit[i] > res:
                res = self.bit[i]
            i -= i & -i
        return res

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    ropes_by_ri = [[] for _ in range(n + 1)]
    for _ in range(m):
        l = int(next(it)); r = int(next(it))
        ropes_by_ri[r].append((l, r))
    q = int(next(it))
    queries_by_y = {}
    ans = [0] * q
    for idx in range(q):
        x = int(next(it)); y = int(next(it))
        queries_by_y.setdefault(y, []).append((idx, x))
    fenw = Fenwick(n)
    current_y = 0
    for y in sorted(queries_by_y.keys()):
        for ry in range(current_y + 1, y + 1):
            for (l, r) in ropes_by_ri[ry]:
                fenw.update(l, r)
        current_y = y
        for idx, x in queries_by_y[y]:
            M = x
            while True:
                A = fenw.query(M)
                if A <= M:
                    break
                M = A
                if M >= y:
                    break
            ans[idx] = M
    out_lines = []
    for v in ans:
        out_lines.append(str(v))
    sys.stdout.write("\n".join(out_lines))

