// Solve: Track (CF style) shortest path with at most k distinct plot types (letters) visited.
// State: (idx, mask) where idx in [0..n*m-1], mask is bitmask of used letters (26 bits).
// S index is start; T index is target. Moving into a cell with a letter L adds that letter to the mask.
// S and T themselves do not contribute to the mask. We cannot revisit S after start.

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n,m,k;
    if(!(cin>>n>>m>>k)) return 0;
    vector<string> g(n);
    for(int i=0;i<n;i++) cin>>g[i];

    int N = n*m;
    auto idx_of = [&](int r,int c){return r*m + c;};
    int S_idx=-1, T_idx=-1;
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            if(g[i][j]=='S') S_idx = idx_of(i,j);
            else if(g[i][j]=='T') T_idx = idx_of(i,j);
        }
    }
    // Build adjacency
    vector<vector<int>> adj(N);
    vector<pair<int,int>> pos(N);
    for(int i=0;i<n;i++) for(int j=0;j<m;j++){
