        pos[id] = {i,j};
    }
    for(int i=0;i<n;i++){
        for(int j=0;j<m;j++){
            int id = idx_of(i,j);
            const int di[4] = {-1,1,0,0};
            const int dj[4] = {0,0,-1,1};
            for(int t=0;t<4;t++){
                int ni=i+di[t], nj=j+dj[t];
                if(ni<0||ni>=n||nj<0||nj>=m) continue;
                adj[id].push_back(idx_of(ni,nj));
            }
        }
    }

    // State representation: key = (idx << 26) | mask
    auto pack = [&](int idx, unsigned int mask)->uint64_t{
        return ( (uint64_t)idx << 26 ) | (uint64_t)mask;
    };
    auto unpack = [&](uint64_t key, int &idx, unsigned int &mask){
        idx = (int)(key >> 26);
        mask = (unsigned int)(key & ((1u<<26)-1));
    };

    uint64_t start_key = pack(S_idx, 0u);
    // Visited states
    unordered_set<uint64_t> visited;
    visited.reserve(1000000);
    visited.insert(start_key);

    // BFS layer containers
    vector<uint64_t> curr;
    curr.push_back(start_key);

    // Parent pointers and letters for path reconstruction
    unordered_map<uint64_t, uint64_t> parent;
    parent.reserve(1000000);
    // letter that was entered to reach a state
    unordered_map<uint64_t, char> letter_entered;
    letter_entered.reserve(1000000);

    auto reconstruct = [&](uint64_t state_key)->string{
        string s;
        while(state_key != start_key){
            auto it = letter_entered.find(state_key);
            if(it==letter_entered.end()) break; // should not happen
            s.push_back(it->second);
            state_key = parent[state_key];
        }
        reverse(s.begin(), s.end());
        return s;
    };

    // Immediate check for direct S -> T adjacency in the first layer (depth 0 -> 1) will happen inside loop

    bool found = false;
    string answer;

    // Layer by layer
    while(!curr.empty()){
        // Step 1: If any current state can reach T in one step, take the lexicographically smallest path to T.
        for(uint64_t s_key : curr){
            int s_idx; unsigned int s_mask;
            unpack(s_key, s_idx, s_mask);
            for(int nb : adj[s_idx]){
                if(nb == S_idx) continue; // cannot revisit S
                if(nb == T_idx){
                    // We can finish here. Reconstruct string to reach s_key.
                    answer = reconstruct(s_key);
                    found = true;
                    break;
                }
            }
            if(found) break;
        }
        if(found) break;

        // Step 2: Expand to next layer using non-T moves, grouped by destination letter to ensure lexicographic order
        vector<uint64_t> next_layer;
        next_layer.reserve(curr.size()*2);
        // For letters 'a' to 'z'
        for(char ch='a'; ch<='z'; ++ch){
            for(uint64_t s_key : curr){
                int s_idx; unsigned int s_mask;
                unpack(s_key, s_idx, s_mask);
