import sys
from itertools import permutations

# Compute maximum overlap where suffix of a matches prefix of b

def max_overlap(a: str, b: str) -> int:
    max_k = min(len(a), len(b))
    for k in range(max_k, 0, -1):
        if a[-k:] == b[:k]:
            return k
    return 0

# Brute-force approach for small n

def best_superstring(strings):
    n = len(strings)
    best = None
    best_len = None
    for perm in permutations(range(n)):
        cur = strings[perm[0]]
        for idx in perm[1:]:
            s = strings[idx]
            k = max_overlap(cur, s)
            cur = cur + s[k:]
        S = cur
        L = len(S)
        counts = {}
        for i in range(L):
            for j in range(i+1, L+1):
                sub = S[i:j]
                counts[sub] = counts.get(sub, 0) + 1
        if not counts:
            continue
        maxfreq = max(counts.values())
        ok = True
        for t in strings:
            if counts.get(t, 0) != maxfreq:
                ok = False
                break
        if ok:
            if best is None or len(S) < best_len or (len(S) == best_len and S < best):
                best = S
                best_len = len(S)
    return best


