#include <bits/stdc++.h>
using namespace std;

// Parametric DP to minimize sum of K non-adjacent gaps on a path
// d[i] = s[i+1]-s[i], i = 1..M, M = N-1

pair<long double,int> solve_lambda(const vector<long long>& d, long double lambda){
    // DP with two previous states to enforce non-adjacency
    long double a_cost = 0.0L; int a_cnt = 0; // dp[i-2]
    long double b_cost = 0.0L; int b_cnt = 0; // dp[i-1]
    for(size_t i = 0; i < d.size(); ++i){
        long double cand1_cost = b_cost; int cand1_cnt = b_cnt; // skip i
        long double cand2_cost = a_cost + (long double)d[i] + lambda; int cand2_cnt = a_cnt + 1; // take i
        bool take = false;
        if (cand2_cost < cand1_cost - 1e-15) take = true;
        else if (fabsl(cand2_cost - cand1_cost) <= 1e-15) {
            if (cand2_cnt > cand1_cnt) take = true; // tie-break: maximize count
        }
        if (take){
            // move to next state with i taken
            a_cost = b_cost; a_cnt = b_cnt;
            b_cost = cand2_cost; b_cnt = cand2_cnt;
        } else {
            // skip i
            a_cost = b_cost; a_cnt = b_cnt;
        }
    }
    return {b_cost, b_cnt};
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int K, N;
    if(!(cin >> K >> N)) return 0;
    vector<long long> t(N);
    for(int i = 0; i < N; ++i) cin >> t[i];
    sort(t.begin(), t.end());
    if(K == 0 || N < 2){
        cout << 0 << "\n";
        return 0;
    }
    // compute diffs between consecutive times
    vector<long long> d;
    d.reserve(N - 1);
    for(int i = 0; i < N - 1; ++i) d.push_back(t[i+1] - t[i]);

    long double low = -1e15L, high = 1e15L;
    pair<long double,int> best = {0.0L, 0};
    // Binary search on lambda to drive count toward K
    for(int it = 0; it < 100; ++it){
        long double mid = (low + high) / 2.0L;
        auto res = solve_lambda(d, mid);
        if(res.second >= K){
            best = res;
            low = mid;
        } else {
            high = mid;
        }
    }
    // Use the final lambda to compute the answer
    auto res = solve_lambda(d, low);
    long double ans_ld = res.first - low * (long double)K;
    long long ans = llround(ans_ld);
    cout << ans << "\n";
    return 0;
}
