#include <bits/stdc++.h>
using namespace std;

void print_ll(long long x) {
  if (x == 0) { putchar('0'); putchar(10); return; }
  bool neg = false;
  if (x < 0) { neg = true; x = -x; }
  char s[32]; int i = 0;
  while (x > 0) { s[i++] = char('0' + (x % 10)); x /= 10; }
  if (neg) putchar('-');
  for (int j = i - 1; j >= 0; --j) putchar(s[j]);
  putchar(10);
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int N, M;
  while (cin >> N >> M) {
    if (N == 0 && M == 0) break;
    vector<int> C(M);
    for (int i = 0; i < M; ++i) cin >> C[i];
    vector<int> X(N);
    for (int i = 0; i < N; ++i) cin >> X[i];
    const long long INF = (1LL << 60);
    array<long long, 256> dp, ndp; dp.fill(INF); dp[128] = 0;
    for (int i = 0; i < N; ++i) {
      ndp.fill(INF);
      int xi = X[i];
      for (int yp = 0; yp < 256; ++yp) {
        long long val = dp[yp]; if (val == INF) continue;
        for (int j = 0; j < M; ++j) {
          int ny = yp + C[j];
          if (ny < 0) ny = 0; else if (ny > 255) ny = 255;
          long long cost = val + 1LL * (xi - ny) * (xi - ny);
          if (cost < ndp[ny]) ndp[ny] = cost;
        }
      }
      dp = ndp;
    }
    long long ans = INF;
    for (int y = 0; y < 256; ++y) if (dp[y] < ans) ans = dp[y];
    print_ll(ans);
  }
  return 0;
}
