struct Fenwick {
  int n; 
  vector<long long> f;
  Fenwick() : n(0) {}
  Fenwick(int n_) : n(n_), f(n_+1, 0) {}
  void init(int n_) { n = n_; f.assign(n+1, 0); }
  void add(int i, long long delta) { for (; i <= n; i += i & -i) f[i] += delta; }
  long long sum(int i) const { long long s = 0; for (; i > 0; i -= i & -i) s += f[i]; return s; }
  // smallest idx such that sum(idx) >= target; assumes 1 <= target <= total_sum
  int lower_bound(long long target) const {
    int idx = 0; long long acc = 0;
    int bit = 1; while ((bit << 1) <= n) bit <<= 1;
    for (int d = bit; d > 0; d >>= 1) {
      int next = idx + d;
      if (next <= n && acc + f[next] < target) {
