struct Fenwick {
  int n; 
  vector<long long> f;
  Fenwick() : n(0) {}
  Fenwick(int n_) : n(n_), f(n_+1, 0) {}
  void init(int n_) { n = n_; f.assign(n+1, 0); }
  void add(int i, long long delta) { for (; i <= n; i += i & -i) f[i] += delta; }
  long long sum(int i) const { long long s = 0; for (; i > 0; i -= i & -i) s += f[i]; return s; }
  int lower_bound(long long target) const {
