#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
static const int64 MOD = 998244353LL;

int64 modpow(int64 a, int64 e) {
    int64 r = 1 % MOD;
    while (e) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int64 modinv(int64 a) {
    return modpow(a, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, c;
    if(!(cin >> n >> c)) return 0;
    vector<int> a(n);
    for(int i = 0; i < n; ++i) cin >> a[i];

    // Frequency of each color 1..c
    vector<int> freq(c + 1, 0);
    for(int x : a) freq[x]++;

    int maxF = 0;
    int minF = INT_MAX;
    for(int y = 1; y <= c; ++y) {
        maxF = max(maxF, freq[y]);
        minF = min(minF, freq[y]);
    }
    // If any color missing, minF will be 0

    // Group colors by frequency
    vector<int> countByFreq(maxF + 1, 0);
    for(int y = 1; y <= c; ++y) countByFreq[freq[y]]++;

    // Precompute factorials up to maxF for binomial coefficients
    vector<int64> fact(maxF + 1, 1), invfact(maxF + 1, 1);
    for(int i = 1; i <= maxF; ++i) fact[i] = fact[i-1] * i % MOD;
    invfact[maxF] = modinv(fact[maxF]);
    for(int i = maxF - 1; i >= 0; --i) invfact[i] = invfact[i+1] * (i+1) % MOD;

    auto C = [&](int n_, int k_) -> int64 {
        if (k_ < 0 || k_ > n_) return 0;
        return fact[n_] * invfact[k_] % MOD * invfact[n_ - k_] % MOD;
    };

    // Build prefix sums pref_f[s] = sum_{t=0..s} C(f, t) for each f with countByFreq[f] > 0
    vector<vector<int64>> pref(maxF + 1); // only filled when countByFreq[f] > 0
    vector<int64> pow2(maxF + 1, 0); // 2^f
    for(int f = 0; f <= maxF; ++f) {
        if (countByFreq[f] == 0) continue;
        pref[f].resize(f + 1);
        pref[f][0] = 1; // C(f,0)
        for(int s = 1; s <= f; ++s) {
            pref[f][s] = (pref[f][s-1] + C(f, s)) % MOD;
        }
        pow2[f] = pref[f][f]; // 2^f
    }

    // Compute A_p for p = 1..minF
    vector<int64> A(minF + 2, 0); // A[p] stored for p>=1; A[minF+1] = 0 by default
    for(int p = 1; p <= minF; ++p) {
        int64 Ap = 1;
        for(int f = 0; f <= maxF; ++f) {
            int cnt = countByFreq[f]; if (cnt == 0) continue;
            int64 Sp;
            if (p > f) {
                Sp = 0;
            } else {
                // S(f, p) = sum_{t=p..f} C(f,t) = 2^f - sum_{t=0..p-1} C(f,t)
                int idx = p - 1; // 0-based index for prefix up to p-1
                int64 prefval = pref[f][idx];
                Sp = (pow2[f] - prefval) % MOD;
                if (Sp < 0) Sp += MOD;
            }
            if (Sp == 0) { Ap = 0; break; }
            Ap = Ap * modpow(Sp, cnt) % MOD;
        }
        A[p] = Ap;
    }

    int64 twoPowN = modpow(2, n);
    int64 A0 = (twoPowN - 1) % MOD; if (A0 < 0) A0 += MOD;
    int64 A1 = (minF >= 1) ? A[1] : 0;
    int64 s0 = (A0 - A1) % MOD; if (s0 < 0) s0 += MOD;

    // Build final answer s_0 .. s_n
    vector<int64> ans(n + 1, 0);
    ans[0] = s0;
    if (minF >= 1) {
