            int64 val = (A[p] - A[p+1]) % MOD; if (val < 0) val += MOD;
            ans[p] = val;
        }
        ans[minF] = A[minF];
    }
    // For p > minF, ans[p] stays 0

    // Output
    for(int i = 0; i <= n; ++i) {
        cout << ans[i];
        if (i < n) cout << ' ';
    }
    cout << '\n';
