import sys


def smallest_by_one_swap(s: str) -> str:
    n = len(s)
    if n < 2:
        return s
    arr = list(s)
    # Compute last position of each character in the string
    last_pos = [-1] * 26
    for i, ch in enumerate(s):
        last_pos[ord(ch) - 65] = i
    # Find the leftmost position i where a smaller character exists to the right
    for i in range(n - 1):
        cur = ord(s[i]) - 65
        for c in range(0, cur):
            j = last_pos[c]
            if j > i:
