import pexpect
import sys

# Simple mock judge for a single test case (N, C)
# Spawns the colors executable and interacts according to the protocol.

def run_case(N, C):
    child = pexpect.spawn('./colors', encoding='utf-8', timeout=20)
    # First query is meaningless: respond with 0
    try:
        child.expect(r'\? 1')
        child.sendline('0')
    except pexpect.EOF:
        print('Program terminated unexpectedly')
        return

    last = 1  # last color used by the program; initial color is 1

    while True:
        try:
            i = child.expect([r'\? (\d+)', r'= (\d+)', pexpect.EOF, pexpect.TIMEOUT])
        except pexpect.EOF:
            break
        if i == 0:
            nextPos = int(child.match.group(1))
            diff = abs(nextPos - last)
            resp = '1' if diff >= C else '0'
            child.sendline(resp)
            last = nextPos
        elif i == 1:
            # Found C
            cval = int(child.match.group(1))
            print('Detected C =', cval)
            break
        else:
            print('Timeout or EOF while waiting for query')
            break
    child.close()

if __name__ == '__main__':
    # Example: test with N=7, C=4
    run_case(N=7, C=4)
    # Exit after one test
    sys.exit(0)
PY
