// moves to move one unit from i to some index > k following allowed moves (same parity).
// This naive approach is mainly for correctness verification on small inputs.

long long solve_naive_one_k(int k, const vector<long long>& a, int n){
    // Precompute, for each i <= k, the minimal distance to some j > k with same parity as i.
    // dist = 1 if there exists j in (k, n] with j % 2 == i % 2; otherwise dist is +INF (unexitable) in naive model.
    // To make it more realistic, allow at most 2 moves by routing through an intermediate index <= k that can exit.
    int INF = 1e9;
    vector<int> dist(n+1, INF); // 1-based
    for(int i=1;i<=k;i++){
        int parity = i & 1;
        int best = INF;
        // direct jump to >k
        for(int j = k+1 + (( (k+1)%2) ^ parity); j <= n; j += 2){ // first >k with same parity
            if((j & 1) == parity){ best = 1; break; }
        }
        if(best==1){ dist[i] = 1; continue; }
        // try two-move path via some i' <= k with same parity and exit possible
        // choose i' in [i..k] with same parity and dist exit from i' exists
        for(int ip = i; ip <= k; ip += 2){ // same parity as i
            int parity2 = ip & 1;
            // check if there exists j>k with same parity as ip
            bool canExit = false;
            for(int j = k+1 + (( (k+1)%2) ^ parity2); j <= n; j += 2){ if((j&1)==parity2){ canExit = true; break; } }
            if(canExit){ best = 2; break; }
        }
        dist[i] = best;
    }
    long long ans = 0;
    for(int i=1;i<=k;i++) ans += a[i] * dist[i];
    return ans;
}

