                if(cross == 0){
                    long long dot = dx*dxj + dy*dyj; // same ray check (positive projection)
                    if(dot > 0){
                        long long dist2_j = dxj*dxj + dyj*dyj;
                        if(dist2_j < dist2_t) blockers[i][t].push_back(j);
                    }
                }
            }
        }
    }

    int K = k, N = n;
    vector<char> killed(N, false);
    vector<char> allowed(N, false);

