        fill(killed.begin(), killed.end(), false);
        fill(allowed.begin(), allowed.end(), false);
        allowed[target] = true;
        for(int i = 0; i < K; ++i){
            for(int b : blockers[i][target]) allowed[b] = true;
        }

        function<bool(int,int)> dfs = [&](int mask, int depth) -> bool {
            if(killed[target]) return true;
            if(__builtin_popcount((unsigned)mask) >= K) return false; // no more stones

            for(int i = 0; i < K; ++i){
                if(mask & (1<<i)) continue; // stone i already used
                for(int j = 0; j < N; ++j){
                    if(!allowed[j] || killed[j]) continue;
                    bool ok = true;
                    for(int b : blockers[i][j]) if(!killed[b]) { ok = false; break; }
                    if(!ok) continue;
                    // shoot monster j with stone i
                    killed[j] = true;
                    int newMask = mask | (1<<i);
                    vector<int> added;
                    // expand allowed with blockers of j across all stones
                    for(int i2 = 0; i2 < K; ++i2){
                        for(int b : blockers[i2][j]) if(!allowed[b]){ allowed[b] = true; added.push_back(b); }
                    }
                    if(j == target) return true;
                    if(dfs(newMask, depth + 1)) return true;
                    for(int b : added) allowed[b] = false;
                    killed[j] = false;
                }
            }
            return false;
        };
        return dfs(0, 0);
    };

    int answer = 0;
    for(int t = 0; t < N; ++t) if(canHitTarget(t)) ++answer;
    cout << answer << "\n";
    return 0;
}
