import sys

# Contribution for a 2x2 block where the top row is fully filled (two 1s above) and the bottom row has bits a,b in {0,1}:
# If a+b == 0 -> 0
# If a+b == 1 -> 1
# If a+b == 2 -> 4

def contrib(a, b):
    s = a + b
    if s == 0:
        return 0
    if s == 1:
        return 1
    return 4


def realize_row(m, rem):
    if rem < 0 or rem > 4 * (m - 1):
        return None
    # DP over columns: for each position j we keep two maps for last bit 0/1
    # pred[j][b][sum] -> (prev_bit, prev_sum)
    pred = [ [dict(), dict()] for _ in range(m) ]
    reachable = [ [set(), set()] for _ in range(m) ]

    # Initialize for j = 1 with s0 in {0,1} and s1 in {0,1}
    for s0 in (0, 1):
        for s1 in (0, 1):
            val = contrib(s0, s1)
            if val <= rem:
                reachable[1][s1].add(val)
                pred[1][s1][val] = (s0, 0)  # previous sum is 0 for base

    # Propagate for j = 2..m-1
    for j in range(2, m):
        for b in (0, 1):
            for prev in (0, 1):
                for sum_prev in list(reachable[j-1][prev]):
                    val = sum_prev + contrib(prev, b)
                    if val <= rem:
                        if val not in reachable[j][b]:
                            reachable[j][b].add(val)
                            pred[j][b][val] = (prev, sum_prev)

    # Check final state
    last_b = None
    for b in (0, 1):
        if rem in reachable[m-1][b]:
            last_b = b
            break
    if last_b is None:
        return None

    # Backtrack to construct S[0..m-1]
    S = [0] * m
    S[m-1] = last_b
    cur = rem
    for j in range(m-1, 0, -1):
        prev_bit, prev_sum = pred[j][S[j]].get(cur, (None, None))
        if prev_bit is None:
            return None
        S[j-1] = prev_bit
        cur = prev_sum

    if cur != 0:
        return None
    return S


def solve_case(n, m, k):
    maxK = 4 * (n - 1) * (m - 1)
    if k > maxK:
        return None

    grid = [ ['.' for _ in range(m)] for __ in range(n) ]
    # backbone: fill first row
    for j in range(m):
        grid[0][j] = '*'

    rem = k
    i = 1
    max_pair = 4 * (m - 1)

    # add full rows while possible
    while rem >= max_pair and i < n:
        grid[i] = ['*' for _ in range(m)]
        rem -= max_pair
        i += 1

    # final partial row if needed
    if rem > 0 and i < n:
        row = realize_row(m, rem)
        if row is None:
            return None
        grid[i] = [ '*' if bit == 1 else '.' for bit in row ]
        rem = 0
        i += 1

    if rem != 0:
        return None
    return grid


def print_grid(grid):
    if grid is None:
        return "-1\n"
    return "\n".join("".join(row) for row in grid) + "\n"


def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0]); idx = 1
    out = []
    for _ in range(t):
        n = int(data[idx]); m = int(data[idx+1]); k = int(data[idx+2]); idx += 3
        grid = solve_case(n, m, k)
        if grid is None:
            out.append("-1\n")
        else:
            out.append(print_grid(grid))
        out.append("\n")  # empty line between test cases
    sys.stdout.write("".join(out).rstrip() + "\n")

if __name__ == "__main__":
    main()
