#!/usr/bin/env python3
import random, subprocess, sys

MOD = 10**9 + 7

def brute(n, m, obs):
    blocked = set()
    for (a, l, r) in obs:
        for j in range(l, r+1):
            blocked.add((a-1, j))
    dp = [0, 1, 0]
    for j in range(2, m+1):
        nd = [0,0,0]
        for i in range(3):
            if (i, j) in blocked:
                nd[i] = 0
            else:
                s = 0
                for prev in (i-1, i, i+1):
                    if 0 <= prev < 3:
                        s = (s + dp[prev]) % MOD
                nd[i] = s
        dp = nd
    return dp[1]

def run_fast(n, m, obs):
    input_text = f"{n} {m}\n" + "\n".join(f"{a} {l} {r}" for (a,l,r) in obs) + "\n"
    out = subprocess.check_output(["python3", "main.py"], input=input_text.encode()).decode().strip()
    return int(out) if out else 0

def test_once():
    m = random.randint(3, 8)
    n = random.randint(0, 4)
    obs = []
    for _ in range(n):
        a = random.randint(1,3)
        l = random.randint(2, m-1)
        r = random.randint(l, m-1)
        obs.append((a, l, r))
    exp = brute(n, m, obs)
    act = run_fast(n, m, obs)
    if exp != act:
        print("Mismatch detected!")
        print("n=", n, "m=", m, "obs=", obs)
        print("expected=", exp, "actual=", act)
        return False
    return True

def main():
    random.seed(0)
    for t in range(200):
        if not test_once():
            sys.exit(1)
    print("All random tests passed.")

if __name__ == '__main__':
    main()
