#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;
    int m = 2 * (n - 1);

    vector<int> head(n + 1, -1);
    vector<int> to(m);
    vector<int> nxt(m);
    int ec = 0;
    auto add_edge = [&](int a, int b){
        to[ec] = b;
        nxt[ec] = head[a];
        head[a] = ec++;
    };

    vector<int> deg(n + 1, 0);
    for (int i = 0; i < n - 1; ++i) {
        int a, b; cin >> a >> b;
        add_edge(a, b);
        add_edge(b, a);
        deg[a]++; deg[b]++;
    }

    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i = 1; i <= n; ++i) if (deg[i] == 1) pq.push(i);

    vector<char> removed(n + 1, false);
    vector<int> ans; ans.reserve(k);

    for (int t = 0; t < k; ++t) {
        int v = -1;
        while (true) {
            int cand = pq.top(); pq.pop();
            if (!removed[cand] && deg[cand] == 1) {
                v = cand; break;
            }
        }
        removed[v] = true;
        ans.push_back(v);

        int u = -1;
        for (int e = head[v]; e != -1; e = nxt[e]) {
            int w = to[e];
            if (!removed[w]) { u = w; break; }
        }
        if (u != -1) {
            deg[u]--;
            if (deg[u] == 1) pq.push(u);
        }
        deg[v] = 0;
    }

    sort(ans.begin(), ans.end());
    for (size_t i = 0; i < ans.size(); ++i) {
        if (i) cout << ' ';
