#!/usr/bin/env python3
import sys

def layout_from_mask(n, mask):
    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            bit = (mask >> (r*n + c)) & 1
            row.append('E' if bit else '.')
        grid.append(''.join(row))
    return grid


def exists_bad_placement(n, grid):
    # Simple placeholder: all-dot or all-E layouts are considered valid.
    all_dot = all(ch == '.' for row in grid for ch in row)
    all_E = all(ch == 'E' for row in grid for ch in row)
    if all_dot or all_E:
        return True
    return False


def collect_valid_layouts(n):
    total = 1 << (n*n)
    valids = []
    for mask in range(total):
        grid = layout_from_mask(n, mask)
        if exists_bad_placement(n, grid):
            valids.append(grid)
    return valids


