#include <bits/stdc++.h>
using namespace std;

using ull = unsigned long long;
using i128 = __int128_t;

ull Cnk(long long n, long long k) {
    if (k < 0 || k > n) return 0;
    if (k > n - k) k = n - k;
    __int128 res = 1;
    for (long long i = 1; i <= k; ++i) {
        res = res * (n - k + i) / i;
    }
    return (ull)res;
}

ull A_no_adj(long long N) {
    const int k = 8;
    if (N < 2 * k) return 0; // cannot place 8 non-adjacent on cycle of N seats
    // A = (N * C(N - k - 1, k - 1)) / k
    ull comb = Cnk(N - k - 1, k - 1);
    __int128 val = ( __int128) N * comb;
    val /= k;
    return (ull)val;
}

// Globals used during combination enumeration
long long gN, gM; // total N, M = N/2 when N is even
unsigned long long g_sum_for_t;

void dfs_comb(int start, int left, vector<int>& comb) {
    if (left == 0) {
        // process this combination comb of size t
        vector<int> rem;
        rem.reserve(2 * (int)comb.size());
        for (int idx : comb) {
            rem.push_back(idx);
            rem.push_back(idx + (int)gM);
        }
        sort(rem.begin(), rem.end());
        int m = (int)rem.size();
        vector<int> Ls;
        Ls.reserve(m);
        for (int i = 0; i < m - 1; ++i) {
            Ls.push_back(rem[i+1] - rem[i] - 1);
        }
        int last = rem[0] + (int)gN - rem[m-1] - 1;
        Ls.push_back(last);
        int t = (int)comb.size();
        int r = 8 - 2 * t;
        unsigned long long ns = 0;
        if (r >= 0) {
            vector<ull> dp(r+1, 0), ndp;
            dp[0] = 1;
            for (int L : Ls) {
                ndp.assign(r+1, 0);
                int maxX = (L + 1) / 2; // maximum non-adjacent on a path of length L
                if (maxX > r) maxX = r;
                for (int y = 0; y <= r; ++y) {
                    if (dp[y] == 0) continue;
                    for (int x = 0; x <= maxX && y + x <= r; ++x) {
                        ull f = Cnk(L - x + 1, x);
                        if (f == 0) continue;
                        ndp[y + x] += dp[y] * f;
                    }
                }
                dp.swap(ndp);
            }
            ns = dp[r];
        } else {
            ns = 0;
        }
        g_sum_for_t += ns;
        return;
    }
    for (int i = start; i <= (int)gM - left; ++i) {
        comb.push_back(i);
        dfs_comb(i + 1, left - 1, comb);
        comb.pop_back();
    }
}

int main() {
