            if (rem[i+1] - rem[i] == 1) return; // adjacent fixed seats
        }
        if (m > 0 && rem[0] == 0 && rem[m-1] == gN - 1) return; // wrap-around adjacency

        // compute L' for each segment between consecutive fixed seats
        vector<long long> Ls; Ls.reserve(m);
        for (int i = 0; i < m - 1; ++i) {
            long long gap = rem[i+1] - rem[i] - 1; // seats strictly between
            long long L = gap - 2; // exclude seats adjacent to the two fixed seats
            if (L < 0) L = 0;
            Ls.push_back(L);
        }
        // wrap-around segment between rem[m-1] and rem[0] around the circle
        long long wrap_gap = rem[0] + gN - rem[m-1] - 1;
        long long Lwrap = wrap_gap - 2;
        if (Lwrap < 0) Lwrap = 0;
        Ls.push_back(Lwrap);
        int t = (int)comb.size();
        int r = 8 - 2 * t;
        unsigned long long ns = 0;
        if (r >= 0) {
            vector<ull> dp(r+1, 0), ndp;
            dp[0] = 1;
            for (long long L : Ls) {
