                int maxX = (L + 1) / 2; // max non-adjacent on a path of length L
                if (maxX > r) maxX = r;
                for (int used = 0; used <= r; ++used) {
                    if (dp[used] == 0) continue;
                    for (int x = 0; x <= maxX && used + x <= r; ++x) {
                        ull f = Cnk(L - x + 1, x);
                        if (f == 0) continue;
                        ndp[used + x] += dp[used] * f;
                    }
                }
                dp.swap(ndp);
            }
            ns = dp[r];
        } else {
            ns = 0;
        }
        g_sum_for_t += ns;
        return;
    }
    for (int i = start; i <= (int)gM - left; ++i) {
        comb.push_back(i);
        dfs_comb(i + 1, left - 1, comb);
        comb.pop_back();
    }
}

