#!/usr/bin/env python3
import sys

MOD = 1000000007

def solve():
    data = sys.stdin.read()
    if not data:
        return
    first_nl = data.find('\n')
    if first_nl == -1:
        S = data.strip()
        T = ""
    else:
        S = data[:first_nl].strip()
        rest = data[first_nl+1:]
        # Build T from rest by keeping only digits and '?'
        T = ''.join(ch for ch in rest if ch.isdigit() or ch == '?')
        if len(T) < len(S):
            lines = data.splitlines()
            if len(lines) >= 2:
                tline = lines[1].strip().replace(" ", "")
                T = tline
    if len(T) != len(S):
        # Fallback to align lengths safely
        T = T.ljust(len(S), '?')[:len(S)]

    n = len(S)
    cnt_tight = 1
    sum_tight = 0
    cnt_loose = 0
    sum_loose = 0

    for i in range(n):
        s_digit = ord(S[i]) - 48
        digits = range(10) if T[i] == '?' else [ord(T[i]) - 48]
        next_cnt_tight = 0
        next_sum_tight = 0
        next_cnt_loose = 0
        next_sum_loose = 0

        # From tight state
        if cnt_tight:
            for d in digits:
                if d > s_digit:
                    continue
                if d == s_digit:
                    next_cnt_tight = (next_cnt_tight + cnt_tight) % MOD
                    next_sum_tight = (next_sum_tight + sum_tight * 10 + cnt_tight * d) % MOD
                else:
                    next_cnt_loose = (next_cnt_loose + cnt_tight) % MOD
                    next_sum_loose = (next_sum_loose + sum_tight * 10 + cnt_tight * d) % MOD

        # From loose state
        if cnt_loose:
            for d in digits:
                next_cnt_loose = (next_cnt_loose + cnt_loose) % MOD
                next_sum_loose = (next_sum_loose + sum_loose * 10 + cnt_loose * d) % MOD

        cnt_tight, sum_tight = next_cnt_tight, next_sum_tight
        cnt_loose, sum_loose = next_cnt_loose, next_sum_loose

    total = (sum_tight + sum_loose) % MOD
    print(total)

