#include <bits/stdc++.h>
using namespace std;

// Min-Cost Max-Flow with potentials (Dijkstra-based)
struct MCMF {
    struct Edge { int to, rev, cap; long long cost; };
    int N; vector<vector<Edge>> G; vector<long long> h, dist; vector<int> pv_v, pv_e;
    MCMF(int n=0){ init(n); }
    void init(int n){ N = n; G.assign(n, {}); h.assign(n, 0); dist.assign(n, 0); pv_v.assign(n, -1); pv_e.assign(n, -1); }
    void addEdge(int u, int v, int cap, long long cost){
        Edge a{v, (int)G[v].size(), cap, cost};
        Edge b{u, (int)G[u].size(), 0, -cost};
        G[u].push_back(a); G[v].push_back(b);
    }
    pair<int,long long> minCostMaxFlow(int s, int t, int maxf){
        int flow = 0; long long cost = 0; const long long INF = (1LL<<60);
        fill(h.begin(), h.end(), 0);
        while(flow < maxf){
            dist.assign(N, INF);
            vector<char> inq(N, 0);
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;
            dist[s] = 0; pq.push({0, s});
            while(!pq.empty()){
                auto cur = pq.top(); pq.pop(); long long d = cur.first; int u = cur.second; if(d != dist[u]) continue;
                for(int i=0;i<(int)G[u].size();++i){ Edge &e = G[u][i]; if(e.cap>0){ long long nd = d + e.cost + h[u] - h[e.to]; if(nd < dist[e.to]){ dist[e.to] = nd; pv_v[e.to] = u; pv_e[e.to] = i; pq.push({nd, e.to}); } } }
            }
            if(dist[t] == INF) break; // cannot push more
            for(int v=0; v<N; ++v) if(dist[v] < INF) h[v] += dist[v];
            int addf = maxf - flow; // bottleneck
            for(int v=t; v!=s; v=pv_v[v]){ Edge &e = G[pv_v[v]][pv_e[v]]; addf = min(addf, e.cap); }
            long long pathCost = 0; for(int v=t; v!=s; v=pv_v[v]){ Edge &e = G[pv_v[v]][pv_e[v]]; pathCost += e.cost; }
            for(int v=t; v!=s; v=pv_v[v]){ Edge &e = G[pv_v[v]][pv_e[v]]; e.cap -= addf; G[v][e.rev].cap += addf; }
            flow += addf; cost += 1LL * addf * pathCost; 
        }
        return {flow, cost};
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    if(!(cin >> n >> m >> k >> c >> d)) return 0;
    vector<int> a(k);
    for(int i=0;i<k;++i) cin >> a[i];
    vector<pair<int,int>> edges(m);
    vector<vector<int>> adj(n+1);
    for(int i=0;i<m;++i){ int x,y; cin >> x >> y; edges[i] = {x,y}; adj[x].push_back(y); adj[y].push_back(x); }

    // BFS from node 1 to get distances
    vector<int> dist(n+1, -1); queue<int> q; dist[1] = 0; q.push(1);
    while(!q.empty()){
        int u = q.front(); q.pop();
        for(int v: adj[u]) if(dist[v] == -1){ dist[v] = dist[u] + 1; q.push(v); }
    }
    int Dmax = 0; for(int i=0;i<k;++i) Dmax = max(Dmax, dist[a[i]]);
    int Tmax = Dmax + k; if(Tmax < 0) Tmax = k; // safety

    int layers = Tmax + 1; int N = layers * n + 2; int S = N - 2; int T = N - 1;
    MCMF mf(N);
    auto id = [&](int node, int t){ return t * n + (node - 1); };

    // Source edges to starting positions at time 0
    for(int i=0;i<k;++i) mf.addEdge(S, id(a[i], 0), 1, 0);

    // Wait edges
    for(int t=0; t<Tmax; ++t){
        for(int u=1; u<=n; ++u){ mf.addEdge(id(u, t), id(u, t+1), k, 0); }
    }

    // Movement edges per street per time, with per-unit congestion costs (k parallel unit edges per street per direction)
    for(int t=0; t<Tmax; ++t){
        for(int i=0;i<m;++i){ int u = edges[i].first, v = edges[i].second;
            for(int w=1; w<=k; ++w){ long long cost = 1LL * d * (2*w - 1); mf.addEdge(id(u, t), id(v, t+1), 1, cost); mf.addEdge(id(v, t), id(u, t+1), 1, cost); }
        }
    }

    // Arrival edges from crossroad 1 at time t to sink with cost c * t
    for(int t=0; t<=Tmax; ++t){ mf.addEdge(id(1, t), T, k, 1LL * c * t); }

    auto res = mf.minCostMaxFlow(S, T, k);
    cout << res.second << "\n";
    return 0;
}
