import subprocess
import sys
from functools import lru_cache

# Brute-force exact solution using DP over remaining vector and bought so far

def brute_cost(a, b):
    n = len(a)
    a_t = tuple(a)
    b_t = tuple(b)

    @lru_cache(None)
    def dfs(rem, bought):
        rem_list = list(rem)
        if sum(rem_list) == 0:
            return 0
        best = 10**9
        for i in range(n):
            if rem[i] > 0:
                price = 1 if bought >= b[i] else 2
                new_rem = list(rem)
                new_rem[i] -= 1
                cost = price + dfs(tuple(new_rem), bought + 1)
                if cost < best:
                    best = cost
        return best

    return dfs(a_t, 0)


def main():
    random.seed(0)
    trials = 200
    for t in range(trials):
        n = random.randint(1, 4)
        a = [random.randint(1, 3) for _ in range(n)]
        if sum(a) > 8:
