import os, sys, re, math
from collections import Counter

# Simple tokenizer: lowercase words, alphabetic + apostrophes
def tokenize(text):
    return re.findall(r"[a-zA-Z']+", text.lower())

# Try to locate training base containing 1/2/3
def load_training_base():
    # If there are directories 1,2,3 in CWD, use current dir
    if os.path.isdir('./1') and os.path.isdir('./2') and os.path.isdir('./3'):
        return '.'
    # Common names for training directories
