        if os.path.isdir(base) and all(os.path.isdir(os.path.join(base, cls)) for cls in ['1','2','3']):
            return base
    return None

def build_model(base):
    counts = {}
    totals = {}
    vocab = set()
    for cls in ['1','2','3']:
        path = os.path.join(base, cls)
        if not os.path.isdir(path):
            continue
        cls_counts = Counter()
        total = 0
        for root, _, files in os.walk(path):
            for fname in files:
                fpath = os.path.join(root, fname)
                try:
                    with open(fpath, 'r', encoding='utf-8', errors='ignore') as f:
                        lines = f.read().splitlines()
                except:
                    continue
                content = "\n".join(lines[2:]) if len(lines) >= 3 else ""
                words = tokenize(content)
                cls_counts.update(words)
                total += len(words)
        counts[cls] = cls_counts
        totals[cls] = total
        vocab.update(cls_counts.keys())
    if not vocab:
        return None
    return {'counts': counts, 'totals': totals, 'vocab': vocab}

def classify_text(text, model):
