    totals = model['totals']
    vocab = model['vocab']
    words = tokenize(text)
    V = len(vocab)
    logps = {}
    for cls in ['1','2','3']:
        total = totals.get(cls, 0)
        cls_counts = counts.get(cls, Counter())
        if total == 0:
            logps[cls] = float('-inf')
            continue
        logp = 0.0
        denom = total + V
        for w in words:
            c = cls_counts.get(w, 0)
            prob = (c + 1) / denom
            logp += math.log(prob)
        logps[cls] = logp
    best = max(logps, key=lambda k: logps[k])
    return best

