    n, m, k = map(int, line.split())
    grid = [list(sys.stdin.readline().rstrip('\n')) for _ in range(n)]

    s = 0
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                s += 1
                if start is None:
                    start = (i, j)

    desired = s - k
    visited = [[False] * m for _ in range(n)]
    stack = []
    if start is not None:
        si, sj = start
        stack.append((si, sj))
        visited[si][sj] = True
        count = 1
        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        while stack and count < desired:
            x, y = stack.pop()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                    visited[nx][ny] = True
                    stack.append((nx, ny))
                    count += 1
                    if count >= desired:
                        break

    out = []
    for i in range(n):
        row = []
        for j in range(m):
            if grid[i][j] == '.':
                row.append('.' if visited[i][j] else 'X')
            else:
                row.append(grid[i][j])
        out.append(''.join(row))
    sys.stdout.write('\n'.join(out))

