#include <bits/stdc++.h>
using namespace std;

static const long long NEG = -(1LL<<60);

struct Node {
    long long best;
    long long maxA;
    long long maxB;
    Node(long long b=NEG, long long a=NEG, long long c=NEG): best(b), maxA(a), maxB(c) {}
};

static Node mergeN(const Node &L, const Node &R) {
    Node res;
    res.best = max(max(L.best, R.best), L.maxA + R.maxB);
    res.maxA = max(L.maxA, R.maxA);
    res.maxB = max(L.maxB, R.maxB);
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if(!(cin >> n >> m)) return 0;
    vector<long long> d(n+1), h(n+1);
    for(int i=1;i<=n;i++) cin >> d[i];
    for(int i=1;i<=n;i++) cin >> h[i];

    int N = 2 * n;
    vector<long long> H(N+1), gap(N+1), P(N+1), A(N+1), B(N+1);
    for(int i=1;i<=N;i++) H[i] = h[(i-1)%n + 1];
    for(int i=1;i<=N-1;i++) gap[i] = d[((i-1)%n) + 1];
    P[1] = 0; for(int i=2;i<=N;i++) P[i] = P[i-1] + gap[i-1];
    for(int i=1;i<=N;i++){ A[i] = 2*H[i] - P[i]; B[i] = 2*H[i] + P[i]; }

    // Segment tree
    vector<Node> seg(4*(N+5));
    function<void(int,int,int)> build = [&](int v,int l,int r){
        if(l==r){ seg[v] = Node(NEG, A[l], B[l]); return; }
        int m = (l+r)/2;
        build(v*2, l, m);
        build(v*2+1, m+1, r);
        seg[v] = mergeN(seg[v*2], seg[v*2+1]);
    };
    function<Node(int,int,int,int,int)> query = [&](int v,int l,int r,int ql,int qr)->Node{
        if(ql>r || qr<l) return Node(NEG, NEG, NEG);
        if(ql<=l && r<=qr) return seg[v];
        int m = (l+r)/2;
        Node L = query(v*2, l, m, ql, qr);
        Node R = query(v*2+1, m+1, r, ql, qr);
        return mergeN(L, R);
    };

    build(1,1,N);

    while(m--){
        int a,b; cin >> a >> b;
        int L,R;
        if(a <= b){ L = b+1; R = a-1 + n; }
        else { L = b+1; R = a-1; }
        Node res = query(1,1,N,L,R);
        cout << res.best << "\n";
    }
    return 0;
}
