    int N = 1<<n;
    vector<long long> dp(N, INF), ndp(N, INF);
    dp[0] = 0;

    // Precompute for each column j: valid masks (T) with distinct letters among i in T, and the cost_j(T) = sum_{i not in T} a[i][j]
    // We'll store for each column a vector of pairs (mask, cost).
    vector<vector<pair<int,long long>>> colMasks(m);
    for(int j=0;j<m;j++){
