        for(int mask=0; mask < N; ++mask){
            bool ok = true;
            unsigned int seen = 0; // 26-bit mask for letters 'a'..'z'
            long long cost = 0;
            for(int i=0;i<n;i++) if(mask & (1<<i)){
                int c = s[i][j]-'a';
                if(seen & (1u<<c)) { ok = false; break; }
                seen |= (1u<<c);
