            if(!ok) continue;
            // cost: change all i not in mask at column j
            cost = 0;
            for(int i=0;i<n;i++) if(!(mask & (1<<i))) cost += a[i][j];
            colMasks[j].push_back({mask, cost});
        }
    }

    // DP across columns
    for(int j=0;j<m;j++){
        fill(ndp.begin(), ndp.end(), INF);
        for(int mask=0; mask<N; ++mask){
            if(dp[mask] == INF) continue;
            // Try to extend by choosing a subset T disjoint from mask
            // We will only consider T that are disjoint. But we precomputed all T per column.
            for(auto &p : colMasks[j]){
                int T = p.first;
                long long cost = p.second;
                if(mask & T) continue; // must be disjoint
                int nmask = mask | T;
                ndp[nmask] = min(ndp[nmask], dp[mask] + cost);
            }
        }
        dp.swap(ndp);
    }

    long long ans = dp[N-1];
    if(ans >= INF/2) ans = -1; // or print ans as computed, depending on problem constraints
