        for(int j=LOG-1; j>=0; --j){ int a = up[cur][j]; if(a && sz[a] < low) cur = a; }
        int cand = up[cur][0];
        if(cand != 0 && sz[cand] >= low && sz[cand] <= high) return true;
        return false;
    };

    // 4) Determine heavy components for each vertex
    vector<int> heavyCount(n+1,0), heavyType(n+1,0), heavyChild(n+1,-1);
    vector<int> ans(n+1,0);
    for(int v=1; v<=n; ++v){
