        if(cnt==0) ans[v] = 1; // already centroid
    }

    // 5) Prepare offline queries for heavy-Child cases
    struct Q{ int x; int l; int r; int v; int coef; };
    vector<Q> queries; queries.reserve(n*2);
    vector<long long> counts(n+1,0);
    for(int v=1; v<=n; ++v){ if(heavyCount[v]==1 && heavyType[v]==1){ int ch = heavyChild[v]; int L = (int)(sz[ch] - LIMIT); int R = LIMIT; // L..R inclusive
            // R-query
            if(R >= 0) queries.push_back({R, tin[ch], tout[ch], v, +1});
            // L-1 query
            int xm1 = L - 1; if(xm1 >= 0) queries.push_back({xm1, tin[ch], tout[ch], v, -1});
        } }
    sort(queries.begin(), queries.end(), [](const Q& a, const Q& b){ return a.x < b.x; });
    sort(Avec.begin(), Avec.end());
    Fenwick bit(n);
    int p = 0; // pointer into Avec
    for(const auto& qu : queries){ while(p < (int)Avec.size() && Avec[p].first <= qu.x){ bit.add(Avec[p].second, 1); ++p; } counts[qu.v] += (long long)qu.coef * bit.rangeSum(qu.l, qu.r); }
    // finalize heavy-Child results
    for(int v=1; v<=n; ++v){ if(heavyCount[v]==1 && heavyType[v]==1){ ans[v] = (counts[v] > 0) ? 1 : 0; } }

    // 6) Finalize heavy-Up cases using ancestor check
    for(int v=1; v<=n; ++v){ if(heavyCount[v]==1 && heavyType[v]==2){ int low = n - LIMIT; int high = min(n, (int)(sz[v] + LIMIT)); if(high < low) ans[v] = 0; else ans[v] = hasAncestorWithSzInRange(v, low, high) ? 1 : 0; } }

    // 7) Print answers
    for(int i=1;i<=n;i++) cout<<ans[i]<<" "; cout<<"\n";

    return 0;
}
