    # Product of first k multipliers
    P = 1
    for i in range(k):
        P *= mults[i]

    # Helper to test if there exists t in [L, U] that is a product of subset from first k elements
    def exists_interval(L, U, k_sub):
        if L > U:
            return False
        k1 = k_sub // 2
        first = mults[:k1]
        second = mults[k1:k_sub]

        def gen(arr):
            res = [1]
            for v in arr:
