// floor_sum from AtCoder Library: sum_{i=0}^{n-1} floor((a*i + b)/m)
long long floor_sum(long long n, long long m, long long a, long long b) {
    if (n <= 0) return 0;
    long long ans = 0;
    while (true) {
        if (a >= m) {
            long long q = a / m;
            i128 x = (i128)(n - 1) * n / 2 * q;
            ans += (long long)x;
            a %= m;
        }
        if (b >= m) {
            long long q = b / m;
            i128 x = (i128)n * q;
            ans += (long long)x;
            b %= m;
        }
        i128 y_max = (i128)a * n + b;
        if (y_max < m) break;
        long long n2 = (long long)(y_max / m);
        long long b2 = (long long)(y_max % m);
        long long a2 = m;
        long long m2 = a;
        n = n2; b = b2; a = a2; m = m2;
    }
    return ans;
}

// Counts number of q in [0, M-1] whose residue modulo Pp lies in [L, R]
long long count_in_interval(long long L, long long R, long long M, long long Pp) {
