    }

    int size = 1; while(size < N) size <<= 1; // size is power of two
    int internal = size - 1; // number of internal nodes per segment tree

    auto idOut = [&](int t)->int { return N + t; };      // t in [1..internal]
    auto idIn  = [&](int t)->int { return N + internal + t; };
    auto Inode  = [&](int i)->int { return N + 2*internal + i; };

    int totalNodes = N + 2*internal + M;
    vector<vector<pair<int,long long>>> adj(totalNodes+1);
    auto addEdge = [&](int u, int v, long long w){ adj[u].push_back({v,w}); };

