    function<void(int,int,int,int,int,vector<int>&)> collectOut =
        [&](int ql, int qr, int idx, int l, int r, vector<int>& pieces){
            if (qr < l || r < ql) return;
            if (ql <= l && r <= qr){
                if (l == r){
                    int pos = l;
                    if (pos < N) pieces.push_back(pos+1);
                } else {
                    pieces.push_back(idOut(idx));
                }
                return;
            }
            int m = (l + r) >> 1;
            collectOut(ql, qr, idx*2, l, m, pieces);
            collectOut(ql, qr, idx*2+1, m+1, r, pieces);
        };

    for(int i=1; i<=M; ++i){
        int l0 = L[i]-1, r0 = R[i]-1; // 0-based
        vector<int> pieces; collectOut(l0, r0, 1, 0, size-1, pieces);
        int Ii = Inode(i);
        for(int node : pieces) addEdge(node, Ii, 0);
    }

    // 3) segIn downward edges: internal -> children; leaves -> vertex (0-cost)
    for(int t=1; t<=internal; ++t){
        int from = idIn(t);
        int lc = t*2, rc = t*2+1;
        if (lc < size) addEdge(from, idIn(lc), 0);
        else { int pos = lc - size; if (pos < N) addEdge(from, pos+1, 0); }
        if (rc < size) addEdge(from, idIn(rc), 0);
        else { int pos = rc - size; if (pos < N) addEdge(from, pos+1, 0); }
    }

    // 4) Ii -> pieces in segIn (cost C[i])
    function<void(int,int,int,int,int,vector<int>&)> collectIn =
        [&](int ql, int qr, int idx, int l, int r, vector<int>& pieces){
            if (qr < l || r < ql) return;
            if (ql <= l && r <= qr){
                if (l == r){
                    int pos = l; if (pos < N) pieces.push_back(pos+1);
                } else {
                    pieces.push_back(idIn(idx));
                }
                return;
            }
            int m = (l + r) >> 1;
            collectIn(ql, qr, idx*2, l, m, pieces);
            collectIn(ql, qr, idx*2+1, m+1, r, pieces);
        };

    for(int i=1; i<=M; ++i){
        int l0 = L[i]-1, r0 = R[i]-1; // 0-based
        vector<int> pieces; collectIn(l0, r0, 1, 0, size-1, pieces);
        int Ii = Inode(i); long long w = C[i];
        for(int node : pieces) addEdge(Ii, node, w);
    }

    // 5) Dijkstra
    const long long INF = (1LL<<62);
    vector<long long> dist(totalNodes+1, INF);
    using P = pair<long long,int>;
    priority_queue<P, vector<P>, greater<P>> pq;
    dist[1] = 0; pq.push({0,1});
    while(!pq.empty()){
        auto [d,u] = pq.top(); pq.pop();
        if(d != dist[u]) continue;
        for(auto &e : adj[u]){
            int v = e.first; long long w = e.second;
            if(dist[v] > d + w){ dist[v] = d + w; pq.push({dist[v], v}); }
        }
    }

    if(dist[N] >= INF/2) cout << -1 << "\n"; else cout << dist[N] << "\n";
    return 0;
}
