#!/usr/bin/env python3
import sys

def simulate(colors):
    # colors: list of length M=2N, values 1..N, each exactly twice
    N = len(colors) // 2
    M = 2 * N
    pos = {}
    for idx, c in enumerate(colors):
        pos.setdefault(c, []).append(idx)
    i = 0
    walked = [0] * (M-1)
    while True:
        c = colors[i]
        a, b = pos[c]
        j = a if a != i else b  # partner door index
        if j < M-1:
            walked[j] = 1
        i = j + 1
        if i >= M:
            break
    return ''.join('1' if x else '0' for x in walked)


def brute(N, s):
    M = 2 * N
    colors = [0] * M
    best = None
    def dfs(pos, max_color):
        nonlocal best
        if best is not None:
            return
        if pos == M:
            if simulate(colors) == s:
                best = colors.copy()
            return
        # try to place an existing color with count < 2
        counts = {c: colors.count(c) for c in range(1, max_color+1)}
        for c in range(1, max_color+1):
            if counts.get(c, 0) < 2:
                colors[pos] = c
                dfs(pos+1, max_color)
                if best is not None:
                    return
        # or introduce a new color if we haven't used N colors yet
        if max_color < N:
            colors[pos] = max_color + 1
            dfs(pos+1, max_color+1)
            if best is not None:
                return
        colors[pos] = 0
    dfs(0, 0)
    return best

if __name__ == '__main__':
    data = sys.stdin.read().strip().split()
    if not data:
        print('No')
        sys.exit(0)
    N = int(data[0]); s = data[1]
    ans = brute(N, s)
    if not ans:
        print('No')
    else:
        print('Yes')
        print(' '.join(map(str, ans)))
PY
