#include <bits/stdc++.h>
using namespace std;

struct Dinic {
    struct Edge { int to; long long cap; int rev; };
    int N; vector<vector<Edge>> G; vector<int> level, it;
    Dinic(int n=0){ init(n); }
    void init(int n){ N=n; G.assign(n, {}); level.resize(n); it.assign(n, 0); }
    void addEdge(int u, int v, long long c){ Edge a{v,c,(int)G[v].size()}; Edge b{u,0,(int)G[u].size()}; G[u].push_back(a); G[v].push_back(b); }
    bool bfs(int s, int t){ fill(level.begin(), level.end(), -1); queue<int> q; level[s]=0; q.push(s); while(!q.empty()){ int u=q.front(); q.pop(); for(const auto &e: G[u]) if(e.cap>0 && level[e.to]<0){ level[e.to]=level[u]+1; q.push(e.to); } } return level[t]>=0; }
    long long dfs(int u, int t, long long f){ if(u==t) return f; for(int &i=it[u]; i<(int)G[u].size(); ++i){ Edge &e = G[u][i]; if(e.cap>0 && level[e.to]==level[u]+1){ long long ret = dfs(e.to, t, min(f, e.cap)); if(ret>0){ e.cap -= ret; G[e.to][e.rev].cap += ret; return ret; } } } return 0; }
    long long maxflow(int s, int t){ long long flow=0; const long long INF = (long long)4e18; while(bfs(s,t)){ fill(it.begin(), it.end(), 0); while(true){ long long f = dfs(s,t,INF); if(!f) break; flow += f; } } return flow; }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W; if(!(cin >> H >> W)) return 0;
    vector<vector<long long>> a(H, vector<long long>(W));
    long long total = 0;
    for(int i=0;i<H;++i){
        for(int j=0;j<W;++j){
            long long x; cin >> x; a[i][j] = x; total += x;
        }
    }
    int N = H*W;
    int S = N, T = N+1;
    Dinic din(N+2);
    auto id = [&](int i, int j){ return i*W + j; };
    long long INF = total + 1; // strictly greater than total

    for(int i=0;i<H;++i){
        for(int j=0;j<W;++j){
            int u = id(i,j);
            if(((i+j)&1)==0){ // black: connect S -> u
                din.addEdge(S, u, a[i][j]);
                // connect to 4-neighbors with INF
                if(i>0) din.addEdge(u, id(i-1,j), INF);
                if(i+1 < H) din.addEdge(u, id(i+1,j), INF);
                if(j>0) din.addEdge(u, id(i,j-1), INF);
                if(j+1 < W) din.addEdge(u, id(i,j+1), INF);
            } else { // white: connect u -> T
                din.addEdge(u, T, a[i][j]);
            }
        }
    }

    long long maxf = din.maxflow(S, T);
    long long ans = total - maxf;
    cout << ans << "\n";
    return 0;
}
